$ctl.VdList.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, [System.Windows.RoutedEventHandler]{
    param($s, $e)
    $b = $e.OriginalSource
    if (-not ($b -is [System.Windows.Controls.Button]) -or -not ($b.Tag -is [VdiskRow])) { return }
    $r = $b.Tag
    if ($script:worker) { Show-Sheet -Title (T '请等当前操作做完') -Text (T '另一个操作还在进行中。') | Out-Null; return }
    switch ($b.Name) {
        'VdOpen' { Open-Location $r.Path }
        'VdCompact' {
            $apps = @(); if ($r.Kind -eq 'docker') { $apps = @('Docker Desktop') }
            if ($apps) {
                $busy = Get-BusyApps $apps
                if ($busy.Count -gt 0) { Show-Sheet -Kind warn -Title (T '请先退出 Docker Desktop') -Text (T '在任务栏右下角的 Docker 图标上右键，选「Quit Docker Desktop」，再回来压缩。') | Out-Null; return }
            }
            $extra = if ($r.Kind -eq 'wsl' -or $r.Kind -eq 'docker') { (T '压缩前会先关闭所有 WSL（wsl --shutdown），正在 WSL 里运行的程序会被结束。') } else { (T '用这个磁盘的虚拟机要先关掉。') }
            if ((Show-Sheet -Title ((T "压缩「{0}」？") -f $r.Name) -Text ((T "{0}`n`n现在 {1}。{2}压缩不会删除里面的任何数据，只把已经空出来的部分还给 Windows，可能要几分钟。") -f $r.Path, $r.SizeText, $extra) -Buttons @((T '取消'), (T '压缩')) -Primary (T '压缩') -Cancel (T '取消')) -ne (T '压缩')) { return }
            $sync.Mode = 'vdisk'; $sync.VdRes = $null
            Start-Op ((T "压缩虚拟磁盘：{0}") -f $r.Name); UI-Busy $true
            Start-Worker @'
SetP @{ Steps = 1; Step = 1; StepName = (Split-Path $arg.Path -Leaf); SubKind = 'slow'; SubStart = (Get-Date); Detail = '' }
$res = @{}; Invoke-CompactVdisk $arg.Path $arg.Kind $res; $sync.VdRes = $res
'@ @{ Path = $r.Path; Kind = $r.Kind }
        }
        'VdMove' {
            $dest = Get-Dest
            if (-not $dest) { Show-Sheet -Kind warn -Title (T '没有可用的搬家目标') -Text (T '请先在「清理 C 盘」页的「搬家目标」里选一块 C 盘以外的硬盘。') | Out-Null; return }
            if ($r.Kind -eq 'wsl') {
                $to = Join-Path (Join-Path $dest 'WSL') $r.Distro
                $ans = Show-Sheet -Title ((T "把 WSL 发行版「{0}」搬到其他盘？") -f $r.Distro) -Text ((T "用 WSL 自己的命令（wsl --manage {0} --move）把它搬到 {1}，现在 {2}。搬之前会先关闭这个发行版，里面正在运行的程序会被结束，请先保存。搬完照常用 wsl 打开，不用改任何设置。需要 WSL 2.5 以后的版本（wsl --update 可以更新）。") -f $r.Distro, $to, $r.SizeText) -Buttons @((T '取消'), (T '搬')) -Primary (T '搬') -Cancel (T '取消')
                if ($ans -ne (T '搬')) { return }
                $sync.Mode = 'wslmove'; $sync.WslRes = $null
                Start-Op ((T "搬到其他盘：WSL {0}") -f $r.Distro); UI-Busy $true
                Start-Worker @'
SetP @{ Steps = 1; Step = 1; StepName = $arg.Distro; SubKind = 'slow'; SubStart = (Get-Date); Detail = '' }
$res = @{}; Invoke-WslMove $arg.Distro $arg.Dest $res; $sync.WslRes = $res
OpLog '搬运' (T 'WSL 发行版搬到其他盘') $arg.Distro $(if ($res.Ok) { $arg.Dest } else { (T '没搬成：') + $res.Out })
'@ @{ Distro = $r.Distro; Dest = $to }
                return
            }
            $apps = switch -Wildcard ($r.Name) { (T '安卓*') { @('Android 模拟器') } 'VirtualBox*' { @('VirtualBox') } 'VMware*' { @('VMware') } default { @() } }
            $defs = Get-ChatApps; $k = @(); $dd = @()
            foreach ($a in $apps) { $k += $defs[$a].P; $dd += $defs[$a].Dirs }
            $item = @{ N = $r.Name; Paths = @($r.Path); Apps = $apps; Kill = @($k); KillDirs = @($dd) }
            $cp = Get-ClosePlan @($item) $apps
            $text = (T "{0}（{1}）整个搬到 {2}，原位置留一个链接，软件照常使用。") -f $r.Path, $r.SizeText, $dest
            if ($cp.Names.Count -gt 0) { $text += ((T "`n`n{0} 正在运行，搬之前会替你关掉它们（正在运行的模拟器或虚拟机会被结束）。") -f $cp.Text) }
            if ((Show-Sheet -Title ((T "把「{0}」搬到其他盘？") -f $r.Name) -Text $text -Buttons @((T '取消'), (T '搬')) -Primary (T '搬') -Cancel (T '取消')) -ne (T '搬')) { return }
            $item.Restrict = $true; $item.Allowed = @($cp.Names)
            $sync.Mode = 'vmove'; $sync.VmRes = $null
            Start-Op ((T "搬到其他盘：{0}") -f $r.Name); UI-Busy $true
            Start-Worker @'
New-Item -ItemType Directory -Path $arg.Dest -Force | Out-Null
SetP @{ Steps = 1; Step = 1; StepName = $arg.Item.N; StepNote = '' }
$res = @{}; Invoke-Move $arg.Item $arg.Dest $res; $sync.VmRes = $res
'@ @{ Item = $item; Dest = $dest }
        }
    }
})

# ------------------------------------------------------------
# 软件管理
# ------------------------------------------------------------
$script:appRows = $null; $script:leftApp = $null
function Load-Apps {
    if ($script:worker) { return }
    $ctl.EmptyApps.Visibility = 'Visible'; $ctl.EmptyAppsText.Text = (T '正在读取已安装的软件，并统计每个占多少空间…')
    $ctl.AppsList.ItemsSource = $null
    $sync.Mode = 'apps'; $sync.AppsResult = $null
    Start-Op (T '统计已安装的软件') -NoCard
    UI-Busy $true
    Start-Worker @'
$out = Get-InstalledApps
$i = 0
SetP @{ Steps = $out.Count + 1; Step = 1; StepName = (T '读取 C 盘的文件表') }
$tree = Get-SysTree
$generic = @($env:SystemRoot, "$env:SystemDrive\Program Files", "$env:SystemDrive\Program Files (x86)", "$env:SystemDrive\ProgramData", $env:LOCALAPPDATA, $env:APPDATA, "$env:LOCALAPPDATA\Programs")
$stopped = $false
foreach ($a in $out) {
    $i++
    $a.Size = $a.Est; $a.Measured = $false
    if ($stopped -or (Stopping)) { $stopped = $true; continue }   # 取消后剩下的用安装时登记的大小
    SetP @{ Steps = $out.Count + 1; Step = $i + 1; StepName = $a.Name; SubKind = 'none' }
    $loc = $a.Location
    if ($loc -and $loc.Length -gt 3 -and ($generic -notcontains $loc) -and (Test-Path -LiteralPath $loc -PathType Container)) {
        $b = Est-Bytes $loc $tree
        if (Stopping) { $stopped = $true; continue }
        if ($b -gt 0) { $a.Size = $b; $a.Measured = $true }
    }
}
$sync.AppsResult = $out
'@ $null
}
function Filter-Apps {
    if ($script:appsView -ne 'apps') { return }
    if (-not $script:appRows) { return }
    $q = ([string]$ctl.AppsSearch.Text).Trim()
    $col = New-Object 'System.Collections.ObjectModel.ObservableCollection[AppRow]'
    $tot = [double]0
    foreach ($r in $script:appRows) {
        if ($ctl.AppsC.IsChecked -and -not $r.OnC) { continue }
        if ($ctl.AppsStore.IsChecked -and $r.Kind -ne 'store') { continue }
        if ($q -and ($r.Name.IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -lt 0) -and ([string]$r.Publisher).IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -lt 0) { continue }
        $col.Add($r); $tot += $r.Size
    }
    $ctl.AppsList.ItemsSource = $col
    $ctl.AppsInfo.Text = (T "{0} 个软件，合计约 {1}") -f $col.Count, (Fmt $tot)
    $ctl.EmptyApps.Visibility = if ($col.Count -gt 0) { 'Collapsed' } else { 'Visible' }
    if ($col.Count -eq 0) { $ctl.EmptyAppsText.Text = (T '没有符合条件的软件') }
}
foreach ($c in @($ctl.AppsAll, $ctl.AppsC, $ctl.AppsStore)) { $c.Add_Checked({ Filter-Apps }) }
$ctl.AppsSearch.Add_TextChanged({ Filter-Apps })
$ctl.BtnAppsRefresh.Add_Click({ $v = Get-AppsView; if ($v -eq 'apps') { Load-Apps } else { $script:startRows.Remove($v); Load-StartRows $v } })
function Build-AppRows($list) {
    $rows = New-Object System.Collections.Generic.List[AppRow]
    foreach ($a in @($list | Sort-Object { [double]$_.Size } -Descending)) {
        $r = New-Object AppRow
        $r.Name = $a.Name; $r.Publisher = $a.Publisher; $r.Version = $a.Version; $r.Location = $a.Location; $r.Uninstall = $a.Uninstall
        $r.Kind = $a.Kind; $r.PackageName = $a.Package; $r.Size = [long]$a.Size
        $r.Icon = if ($a.Name) { $a.Name.Substring(0, 1).ToUpper() } else { '?' }
        $r.SizeText = if ($a.Size -gt 0) { $(if ($a.Measured) { '' } else { (T '约 ') }) + (Fmt $a.Size) } else { '—' }
        $r.OnC = (-not $a.Location) -or $a.Location.StartsWith($env:SystemDrive, [StringComparison]::OrdinalIgnoreCase)
        $r.LocReg = [bool]$a.LocReg
        $movedTo = ''
        if ($a.Location -and $r.OnC -and $a.Kind -ne 'store') {
            $movedTo = LinkTarget $a.Location
            if (-not $movedTo) { $up = Get-LinkedAncestor $a.Location; if ($up) { $t = LinkTarget $up; if ($t) { $movedTo = Join-Path $t.TrimEnd('\') $a.Location.Substring($up.Length).TrimStart('\') } } }
        }
        if ($movedTo) { $r.OnC = $false }
        $r.CanMove = $r.OnC -and [bool]$a.Location
        $d = ''
        if ($a.Date -match '^(\d{4})(\d{2})(\d{2})$') { $d = "{0}-{1}-{2}" -f $matches[1], $matches[2], $matches[3] }
        $r.Date = $d
        $parts = @()
        if ($a.Publisher) { $parts += $a.Publisher }
        if ($a.Version) { $parts += ((T '版本 ') + $a.Version) }
        if ($d) { $parts += ((T '安装于 ') + $d) }
        if ($a.Kind -eq 'store') { $parts += (T '应用商店') }
        if ($movedTo) { $parts += ((T "已搬到 {0}") -f $movedTo.TrimEnd('\')) } elseif ($a.Location) { $parts += $a.Location } else { $parts += (T '没有记录安装位置') }
        $r.Meta = $parts -join ' · '
        $rows.Add($r)
    }
    $script:appRows = $rows
    Filter-Apps
}
# 软件整个搬到其他盘
function Start-AppMove($r) {
    UI-Log ((T "检查「{0}」能不能搬") -f $r.Name)
    $win.Cursor = [System.Windows.Input.Cursors]::Wait
    try { $why = Get-AppMoveBlock $r $sync.AppsResult } finally { $win.Cursor = $null }
    if ($why -eq 'store') {
        $ans = Show-Sheet -Title (T '应用商店的软件由 Windows 管理') -Text ((T "「{0}」是从应用商店装的，本工具不能搬它。`n`n有的应用可以在 Windows 设置里换盘：设置 → 应用 → 已安装的应用，点它右边的「…」，选「移动」（没有这个选项就是不支持）。") -f $r.Name) -Buttons @((T '好'), (T '打开 Windows 设置')) -Primary (T '打开 Windows 设置') -Cancel (T '好')
        if ($ans -eq (T '打开 Windows 设置')) { try { Start-Process 'ms-settings:appsfeatures' } catch {} }
        return
    }
    if ($why) { Show-Sheet -Kind warn -Title ((T "「{0}」不适合搬") -f $r.Name) -Text $why | Out-Null; return }
    $dest = Get-Dest
    if (-not $dest) { Show-Sheet -Kind warn -Title (T '没有可用的搬家目标') -Text (T '这台电脑没有 C 盘以外的硬盘，或者还没选搬家目标。请先在「清理 C 盘」页的「搬家目标」里选一块硬盘。') | Out-Null; return }
    $loc = ([string]$r.Location).TrimEnd('\')
    # 资源管理器加载了它的组件（右键菜单、图标叠加等）时，文件夹会一直被占着
    $ex = @()
    foreach ($p in @(Get-Process -Name explorer -ErrorAction SilentlyContinue)) {
        try { foreach ($m in $p.Modules) { if (([string]$m.FileName).StartsWith("$loc\", [StringComparison]::OrdinalIgnoreCase)) { $ex += $m.ModuleName } } } catch {}
    }
    if ($ex.Count -gt 0) {
        Show-Sheet -Kind warn -Title ((T "「{0}」不适合搬") -f $r.Name) -Text ((T "它给资源管理器装了右键菜单之类的组件（{0}），桌面和文件夹窗口一直开着这些文件，文件夹被占着搬不了。这类软件通常不大，建议留在 C 盘。") -f (@($ex | Select-Object -Unique -First 3) -join (T '、'))) | Out-Null
        return
    }
    $running = Get-ProcsInside @($loc)
    $small = if ($r.Size -gt 0 -and $r.Size -lt 100MB) { (T "`n`n它只占 {0}，搬走腾出的空间不多。") -f $r.SizeText } else { '' }
    $text = (T "把安装文件夹 {0}（{1}）整个搬到 {2}，C 盘原位置留一个链接。桌面快捷方式、开始菜单、卸载和自动更新都照常可用，不用重装。`n`n搬之前先核对两边的文件完全一致，再删掉 C 盘上的那份。{3}") -f $loc, $r.SizeText, $dest, $small
    if ($running.Count -gt 0) { $text += (T "`n`n{0} 正在运行，搬之前会替你关掉（没保存的内容请先保存）。") -f ($running -join (T '、')) }
    $text += (T "`n`n要注意：{0} 盘要一直接着；以后软件大版本升级时，个别安装程序会把它重新装回 C 盘，到时在这里再搬一次就好。要搬回来，到「搬家管理」点「搬回 C 盘」。") -f $dest.Substring(0, 1)
    $btn = if ($running.Count -gt 0) { (T '关掉并搬走') } else { (T '搬到其他盘') }
    if ((Show-Sheet -Title ((T "把「{0}」搬到其他盘？") -f $r.Name) -Text $text -Buttons @((T '取消'), $btn) -Primary $btn -Cancel (T '取消')) -ne $btn) { return }
    $item = @{ N = $r.Name; Paths = @($loc); Apps = @(); Kill = @(); KillDirs = @(); Restrict = $true; Allowed = @($running)
        BusyHint = (T '还有程序开着里面的文件。请退出这个软件（包括屏幕右下角托盘里的图标），关掉打开着这个文件夹的窗口，再搬一次；已经复制好的部分下次直接用，很快') }
    $sync.Mode = 'appmove'; $sync.AmRes = $null; $script:appMoveRow = $r
    Start-Op ((T "搬到其他盘：{0}") -f $r.Name); UI-Busy $true
    Start-Worker @'
New-Item -ItemType Directory -Path $arg.Dest -Force | Out-Null
SetP @{ Steps = 1; Step = 1; StepName = $arg.Item.N; StepNote = '' }
$res = @{ Done = 0; Fail = 0; Wait = 0; Moved = [double]0; Dest = @(); Msgs = @() }
Invoke-AppMove $arg.Item $arg.Dest $res
$sync.AmRes = $res
'@ @{ Item = $item; Dest = $dest }
}
# 把注册表里的卸载命令拆成「程序 + 参数」
function Split-Command([string]$cmd) {
    $cmd = $cmd.Trim()
    if ($cmd -match '(?i)^"?(?:[a-z]:\\[^"]*\\)?msiexec(\.exe)?"?\s+(.*)$') { return @("$env:SystemRoot\System32\msiexec.exe", ($matches[2] -replace '(?i)/I\s*\{', '/X{')) }
    if ($cmd.StartsWith('"')) { $e = $cmd.IndexOf('"', 1); if ($e -gt 0) { return @($cmd.Substring(1, $e - 1), $cmd.Substring($e + 1).Trim()) } }
    $m = [regex]::Match($cmd, '(?i)^(.+?\.exe)(\s+.*)?$')
    if ($m.Success) { return @($m.Groups[1].Value, $m.Groups[2].Value.Trim()) }
    return @($cmd, '')
}
$ctl.AppsList.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, [System.Windows.RoutedEventHandler]{
    param($s, $e)
    $b = $e.OriginalSource
    if (-not ($b -is [System.Windows.Controls.Button]) -or -not ($b.Tag -is [AppRow])) { return }
    $r = $b.Tag
    if ($b.Name -eq 'AppOpen') {
        if ($r.Location -and (Test-Path -LiteralPath $r.Location)) { Open-Location $r.Location } else { Show-Sheet -Title (T '没有记录安装位置') -Text (T '这个软件的安装程序没有写明装在哪里。') | Out-Null }
        return
    }
    if ($b.Name -eq 'AppUpgrade') { Start-WingetUpgrade $r.UpgradeId $r.Name; return }
    if ($script:worker) { Show-Sheet -Title (T '请等当前操作做完') -Text (T '另一个操作还在进行中。') | Out-Null; return }
    if ($b.Name -eq 'AppMove') { Start-AppMove $r; return }
    $txt = if ($r.Kind -eq 'store') { (T "从应用商店卸载 {0}（{1}）。") -f $r.Name, $r.SizeText } else { (T "会打开 {0} 自带的卸载程序，按它的提示一步步操作即可。卸载完回到这里点「检查残留」，看看还有没有剩下的文件夹。") -f $r.Name }
    if ((Show-Sheet -Kind warn -Title ((T "卸载「{0}」？") -f $r.Name) -Text ($txt + (T "`n`n卸载会删除这个软件，它保存在软件里的数据可能一起被删掉。")) -Buttons @((T '取消'), (T '卸载')) -Primary (T '卸载') -Cancel (T '取消')) -ne (T '卸载')) { return }
    if ($r.Kind -eq 'store') {
        $sync.Mode = 'uninst'; $sync.UninstRes = $null
        Start-Op ((T "卸载 {0}") -f $r.Name); UI-Busy $true
        Start-Worker @'
$ok = $true; $msg = ''
try { Remove-AppxPackage -Package $arg.Pkg -ErrorAction Stop } catch { $ok = $false; $msg = $_.Exception.Message }
OpLog '卸载' (T '卸载应用商店软件') $arg.Name $(if ($ok) { ((T "约 {0}") -f $(GB $arg.Size)) } else { (T '失败：') + $msg })
$sync.UninstRes = @{ Ok = $ok; Msg = $msg; Name = $arg.Name }
'@ @{ Pkg = $r.PackageName; Name = $r.Name; Size = [double]$r.Size }
        return
    }
    $pc = Split-Command $r.Uninstall
    try {
        if ($pc[1]) { Start-Process -FilePath $pc[0] -ArgumentList $pc[1] -ErrorAction Stop } else { Start-Process -FilePath $pc[0] -ErrorAction Stop }
        OpLog '卸载' (T '打开卸载程序') $r.Name $r.Uninstall
        $script:leftApp = $r
        $ctl.AppsLeftText.Text = (T "已打开「{0}」的卸载程序。卸载完成后点「检查残留」，看看还剩下哪些文件夹。") -f $r.Name
        $ctl.AppsLeftBox.Visibility = 'Visible'
    } catch { Show-Sheet -Kind warn -Title (T '打不开卸载程序') -Text ("{0}`n`n{1}" -f $r.Uninstall, $_.Exception.Message) | Out-Null }
})
$ctl.BtnAppsLeftClose.Add_Click({ $ctl.AppsLeftBox.Visibility = 'Collapsed'; $script:leftApp = $null })
# 卸载后可能留下的文件夹：以软件名命名的、装在原来位置的。发行商的总文件夹（比如 Tencent）不算
function Find-Leftovers($r) {
    $names = New-Object System.Collections.Generic.List[string]
    $n0 = [string]$r.Name
    $shared = @('Tencent','Microsoft','Google','Adobe','Intel','NVIDIA','Apple','Packages','Programs','Temp','Common Files','Mozilla','Oracle','Java','Python','Steam','Microsoft Office',
        'Games','Program Files','Program Files (x86)','ProgramData','Users','Windows','Downloads','Documents','Desktop')
    # 太短或太常见的名字（bin、app、tools……）会撞上别的软件的文件夹，不拿来找
    $generic = @('bin','app','apps','application','applications','program','programs','software','tools','data','current','x64','x86','common','setup','install','update','client','launcher')
    $ok = { param($n) $n -and $n.Length -ge 4 -and ($generic -notcontains $n.ToLowerInvariant()) -and ($shared -notcontains $n) }
    foreach ($n in @($n0, ($n0 -replace '\s*\(.*?\)\s*', ' ').Trim(), ($n0 -replace '\s+v?\d+([\.\d]+)?\s*$', '').Trim(), ($n0 -replace '\s+(x64|x86|64-bit|32-bit)$', '').Trim())) {
        if ((& $ok $n) -and -not $names.Contains($n)) { $names.Add($n) }
    }
    $norm = { param($x) (([string]$x).ToLowerInvariant() -replace '[^\p{L}\p{N}]', '') }
    $loc = ([string]$r.Location).TrimEnd('\')
    $useLoc = $false
    if ($loc -and $loc.Length -gt 3) {
        $leaf = Split-Path $loc -Leaf
        $ln = & $norm $leaf; $nn = & $norm $n0
        $matchName = $ln.Length -ge 3 -and $nn.Length -ge 3 -and ($nn.Contains($ln) -or $ln.Contains($nn))
        # 装在盘符下面一层（比如 D:\Games）又和软件名对不上的，多半是装软件的总文件夹，不当残留
        $topLevel = ((Split-Path $loc -Parent).TrimEnd('\').Length -le 2)
        if ((& $ok $leaf) -and -not ($topLevel -and -not $matchName)) {
            $useLoc = $true
            if (-not $names.Contains($leaf)) { $names.Add($leaf) }
        }
    }
    # 别的还装着的软件用的文件夹，不能当成这个软件的残留
    $others = @()
    if ($sync.AppsResult) { foreach ($a in $sync.AppsResult) { $l = ([string]$a.Location).TrimEnd('\'); if ($l -and $l.Length -gt 3 -and [string]$a.Name -ne $n0) { $others += $l } } }
    $bases = @($env:APPDATA, $env:LOCALAPPDATA, "$env:LOCALAPPDATA\Programs", "$env:SystemDrive\ProgramData", "$env:SystemDrive\Program Files", "$env:SystemDrive\Program Files (x86)")
    $pub = ([string]$r.Publisher).Trim()
    $cands = New-Object System.Collections.Generic.List[string]
    if ($useLoc -and (Test-Path -LiteralPath $loc)) { $cands.Add($loc) }
    foreach ($b in $bases) {
        foreach ($n in $names) {
            if ($shared -contains $n) { continue }
            foreach ($c in @((Join-Path $b $n), $(if ($pub -and $pub.Length -ge 2) { Join-Path (Join-Path $b $pub) $n } else { '' }))) {
                if ($c -and (Test-Path -LiteralPath $c -PathType Container) -and -not $cands.Contains($c)) { $cands.Add($c) }
            }
        }
    }
    $out = @()
    foreach ($c in $cands) {
        if (IsLink $c) { continue }
        if (Get-DeleteBlock $c -Leftover) { continue }
        $cf = $c.TrimEnd('\'); $inUse = $false
        foreach ($o in $others) { if ($o -ieq $cf -or $o.StartsWith("$cf\", [StringComparison]::OrdinalIgnoreCase) -or $cf.StartsWith("$o\", [StringComparison]::OrdinalIgnoreCase)) { $inUse = $true; break } }
        if ($inUse) { continue }
        $out += @{ Path = $c; Bytes = (DirBytes $c) }
    }
    return ,$out
}
$ctl.BtnAppsLeft.Add_Click({
    $r = $script:leftApp
    if (-not $r -or $script:worker) { return }
    $still = $false
    foreach ($k in 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*') {
        foreach ($p in @(Get-ItemProperty $k -ErrorAction SilentlyContinue)) { if ([string]$p.DisplayName -eq $r.Name) { $still = $true } }
    }
    if ($still) { Show-Sheet -Title (T '看起来还没卸载完') -Text ((T "系统里还登记着「{0}」。等卸载程序走完，再点「检查残留」。") -f $r.Name) | Out-Null; return }
    $left = Find-Leftovers $r
    if (-not $left -or $left.Count -eq 0) {
        Show-Sheet -Kind done -Title (T '没发现残留') -Text ((T "「{0}」已经卸载干净了。") -f $r.Name) | Out-Null
        $ctl.AppsLeftBox.Visibility = 'Collapsed'; $script:leftApp = $null; Load-Apps; return
    }
    $items = @($left | ForEach-Object { (T "{0}（{1}）") -f $_.Path, (Fmt $_.Bytes) })
    $ans = Show-Sheet -Kind danger -Title ((T "「{0}」留下了 {1} 个文件夹") -f $r.Name, $left.Count) -Text (T '这些文件夹以软件名命名，多半是卸载后剩下的设置和缓存。会移到回收站，需要的话还能恢复。') -Items $items `
        -Confirm (T '我已确认这些是已卸载软件留下的，删除不会给我带来损失。') -Buttons @((T '先不删'), (T '移到回收站')) -Primary (T '移到回收站') -Cancel (T '先不删')
    if ($ans -ne (T '移到回收站')) { return }
    $sync.Mode = 'leftdel'; $sync.LeftRes = $null
    Start-Op ((T "清理「{0}」的残留") -f $r.Name); UI-Busy $true
    Start-Worker @'
$n = 0; $i = 0
foreach ($x in $arg.Items) {
    if (Stopping) { break }
    $i++
    SetP @{ Steps = $arg.Items.Count; Step = $i; StepName = $x.Path; SubKind = 'none' }
    if (Get-DeleteBlock $x.Path -Leftover) { continue }
    [void][FsTools]::Recycle($x.Path, [long]$sync.Hwnd)
    $ok = -not (Test-Path -LiteralPath $x.Path)
    if ($ok) { $n++ }
    OpLog '删除' ((T "软件残留：移到回收站（{0}）") -f $arg.Name) $x.Path $(if ($ok) { GB $x.Bytes } else { (T '没删掉，可能被占用') })
}
$sync.LeftRes = @{ Count = $n; Name = $arg.Name }
'@ @{ Items = $left; Name = $r.Name }
})

# ---------- 开机启动 / 计划任务 / 右键菜单：同一个列表，按视图换内容 ----------
$script:startRows = @{}   # kind -> List[StartRow]
$script:appsView = 'apps'
function Get-AppsView { if ($ctl.AppsViewStartup.IsChecked) { 'startup' } elseif ($ctl.AppsViewTasks.IsChecked) { 'task' } elseif ($ctl.AppsViewMenu.IsChecked) { 'shellex' } elseif ($ctl.AppsViewLeft.IsChecked) { 'leftover' } else { 'apps' } }
function Show-AppsView {
    $v = Get-AppsView; $script:appsView = $v
    $isApps = ($v -eq 'apps')
    $ctl.AppsList.Visibility = if ($isApps) { 'Visible' } else { 'Collapsed' }
    $ctl.StartList.Visibility = if ($isApps) { 'Collapsed' } else { 'Visible' }
    $ctl.AppsFilterBox.Visibility = if ($isApps) { 'Visible' } else { 'Collapsed' }
    $ctl.BtnAppsUpdates.Visibility = if ($isApps -and $script:appsUpdatesAllowed) { 'Visible' } else { 'Collapsed' }
    if ($isApps) { Filter-Apps; return }
    if (-not $script:startRows.ContainsKey($v)) { Load-StartRows $v } else { Filter-StartRows }
}
function Filter-StartRows {
    $v = $script:appsView
    if ($v -eq 'apps' -or -not $script:startRows.ContainsKey($v)) { return }
    $q = ([string]$ctl.AppsSearch.Text).Trim()
    $col = New-Object 'System.Collections.ObjectModel.ObservableCollection[StartRow]'
    foreach ($r in $script:startRows[$v]) {
        if ($q -and ($r.Name.IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -lt 0) -and ([string]$r.Meta).IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -lt 0 -and ([string]$r.Detail).IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -lt 0) { continue }
        $col.Add($r)
    }
    $ctl.StartList.ItemsSource = $col
    $on = @($col | Where-Object { $_.Enabled }).Count
    $ctl.AppsInfo.Text = switch ($v) {
        'startup' { (T "{0} 个开机启动项，{1} 个已启用") -f $col.Count, $on }
        'task'    { (T "{0} 个第三方计划任务，{1} 个已启用（Windows 自己的不列）") -f $col.Count, $on }
        'leftover' { $tb = [double]0; foreach ($r in $col) { $tb += [double]$r.Key2 }; (T "{0} 个可能是残留的文件夹，共 {1}。只是猜测：名字对不上任何已装软件、没有程序在用、一个月没动过") -f $col.Count, (Fmt $tb) }
        default   { (T "{0} 个第三方右键菜单扩展，{1} 个已启用（系统自带的不列）") -f $col.Count, $on }
    }
    $ctl.EmptyApps.Visibility = if ($col.Count -gt 0) { 'Collapsed' } else { 'Visible' }
    if ($col.Count -eq 0) { $ctl.EmptyAppsText.Text = switch ($v) { 'startup' { (T '没有开机启动项') } 'task' { (T '没有第三方的计划任务') } 'leftover' { (T '没找到像是残留的文件夹') } default { (T '没有第三方的右键菜单扩展') } } }
}
function Load-StartRows([string]$kind) {
    if ($script:worker) { return }
    $ctl.StartList.ItemsSource = $null
    $ctl.EmptyApps.Visibility = 'Visible'; $ctl.EmptyAppsText.Text = (T '正在读取…')
    if ($kind -eq 'leftover') {
        $ctl.EmptyAppsText.Text = (T '正在找已卸载软件可能留下的文件夹（要看一遍软件数据目录，几十秒）…')
        $sync.Mode = 'leftovers'; $sync.LeftoverResult = $null
        Start-Op (T '查找残留文件夹') -NoCard; UI-Busy $true
        Start-Worker @'
$apps = if ($sync.AppsResult) { $sync.AppsResult } else { Get-InstalledApps }
$sync.LeftoverResult = @(Get-OrphanFolders $apps)
'@ $null
        return
    }
    $sync.Mode = 'startup'; $sync.StartResult = $null; $sync.StartKind = $kind
    Start-Op $(switch ($kind) { 'startup' { (T '读取开机启动项') } 'task' { (T '读取计划任务') } default { (T '读取右键菜单扩展') } }) -NoCard
    UI-Busy $true
    Start-Worker @'
$k = $arg.Kind
$sync.StartResult = switch ($k) { 'startup' { @(Get-StartupItems) } 'task' { @(Get-UserTasks) } default { @(Get-ContextMenuItems) } }
'@ @{ Kind = $kind }
}
function Build-StartRows([string]$kind, $list) {
    $rows = New-Object System.Collections.Generic.List[StartRow]
    $srcText = @{ HKCU = (T '注册表 · 当前用户'); HKLM = (T '注册表 · 所有用户'); HKLM32 = (T '注册表 · 所有用户 (32 位)'); UserFolder = (T '「启动」文件夹 · 当前用户'); CommonFolder = (T '「启动」文件夹 · 所有用户') }
    foreach ($x in @($list)) {
        $r = New-Object StartRow
        $r.Kind = $kind; $r.Name = [string]$x.Name
        switch ($kind) {
            'startup' {
                $exe = Get-CommandExe ([string]$x.Cmd)
                $co = Get-FileCompany $exe
                $r.Meta = (@($srcText[[string]$x.Src], $co) | Where-Object { $_ }) -join ' · '
                $r.Detail = [string]$x.Cmd
                $r.Open = if ($exe -and (Test-Path -LiteralPath $exe)) { $exe } else { '' }
                $r.Key1 = [string]$x.Approved; $r.Key2 = [string]$x.Val
                $r.Enabled = [bool]$x.Enabled
            }
            'leftover' {
                $r.Name = Split-Path ([string]$x.Path) -Leaf
                $r.Meta = (T "{0} · 最后改动 {1:yyyy-MM-dd}") -f (Fmt ([double]$x.Bytes)), $x.Modified
                $r.Detail = [string]$x.Path; $r.Open = [string]$x.Path
                $r.Key1 = [string]$x.Path; $r.Key2 = [string]([double]$x.Bytes); $r.Size = (Fmt ([double]$x.Bytes))
            }
            'task' {
                $parts = @(); if ($x.Author) { $parts += [string]$x.Author }; $parts += ((T '任务 ') + [string]$x.Path + [string]$x.Name)
                if ($x.Desc) { $parts += ([string]$x.Desc) }
                $r.Meta = ($parts -join ' · ')
                $r.Detail = [string]$x.Cmd
                $exe = Get-CommandExe ([string]$x.Cmd)
                $r.Open = if ($exe -and (Test-Path -LiteralPath $exe)) { $exe } else { '' }
                $r.Key1 = [string]$x.Path; $r.Key2 = [string]$x.Name
                $r.Ours = [bool]$x.Ours
                $r.Enabled = ([string]$x.State -ne 'Disabled')
            }
            default {
                $parts = @(); if ($x.Company) { $parts += [string]$x.Company }; $parts += ((T '出现在：') + (@($x.Where) -join (T '、')))
                $r.Meta = ($parts -join ' · ')
                $r.Detail = [string]$x.Dll
                $r.Open = if ($x.Dll -and (Test-Path -LiteralPath $x.Dll)) { [string]$x.Dll } else { '' }
                $r.Key1 = [string]$x.Clsid
                $r.Enabled = [bool]$x.Enabled
            }
        }
        $rows.Add($r)
    }
    $sorted = New-Object System.Collections.Generic.List[StartRow]
    $ordered = if ($kind -eq 'leftover') { @($rows | Sort-Object { -[double]$_.Key2 }) } else { @($rows | Sort-Object { -not $_.Enabled }, Name) }
    foreach ($r in $ordered) { $sorted.Add($r) }
    $script:startRows[$kind] = $sorted
    if ($script:appsView -eq $kind) { Filter-StartRows }
}
function Set-StartRow($r, [bool]$on) {
    try {
        switch ($r.Kind) {
            'startup' { Set-StartupEnabled $r.Key1 $r.Key2 $on }
            'task'    { if ($on) { Enable-ScheduledTask -TaskPath $r.Key1 -TaskName $r.Key2 -ErrorAction Stop | Out-Null } else { Disable-ScheduledTask -TaskPath $r.Key1 -TaskName $r.Key2 -ErrorAction Stop | Out-Null } }
            default   { Set-ContextMenuEnabled $r.Key1 $on }
        }
    } catch { Show-Sheet -Kind warn -Title $(if ($on) { (T '没启用成') } else { (T '没禁用成') }) -Text $_.Exception.Message | Out-Null; return }
    $r.Enabled = $on
    $what = switch ($r.Kind) { 'startup' { if ($on) { (T '启用开机启动项') } else { (T '禁用开机启动项') } } 'task' { if ($on) { (T '启用计划任务') } else { (T '禁用计划任务') } } default { if ($on) { (T '启用右键菜单扩展') } else { (T '禁用右键菜单扩展') } } }
    OpLog '系统设置' $what $r.Name $r.Detail
    UI-Log ((T "{0}：{1}") -f $what, $r.Name)
    if ($r.Kind -eq 'shellex') { $ctl.AppsInfo.Text = (T '右键菜单的改动对新打开的资源管理器窗口生效；还没生效的话注销再登录一次') }
    else { Filter-StartRows }
}
foreach ($rb in @($ctl.AppsViewApps, $ctl.AppsViewStartup, $ctl.AppsViewTasks, $ctl.AppsViewMenu, $ctl.AppsViewLeft)) { $rb.Add_Checked({ Show-AppsView }) }
$ctl.AppsSearch.Add_TextChanged({ Filter-StartRows })
$ctl.StartList.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, [System.Windows.RoutedEventHandler]{
    param($s, $e)
    $b = $e.OriginalSource
    if (-not ($b -is [System.Windows.Controls.Button]) -or -not ($b.Tag -is [StartRow])) { return }
    $r = $b.Tag
    if ($b.Name -eq 'StartOpen') { if ($r.Open) { Open-Location $r.Open }; return }
    if ($b.Name -ne 'StartToggle' -or $r.Ours) { return }
    if ($r.Kind -eq 'leftover') {
        if ($script:worker) { Show-Sheet -Title (T '请等当前操作做完') -Text (T '另一个操作还在进行中。') | Out-Null; return }
        $ans = Show-Sheet -Kind danger -Title ((T "把「{0}」移到回收站？") -f $r.Name) -Text ((T "{0}（{1}）。这只是猜测：名字对不上任何已装软件、没有程序在用、一个月没动过。先点「打开位置」看一眼里面是什么。移到回收站后还能恢复。") -f $r.Detail, $r.Size) `
            -Confirm (T '我看过了，这是已卸载软件留下的，删除不会给我带来损失。') -Buttons @((T '先不删'), (T '移到回收站')) -Primary (T '移到回收站') -Cancel (T '先不删')
        if ($ans -ne (T '移到回收站')) { return }
        if (Get-DeleteBlock $r.Detail -Leftover) { Show-Sheet -Kind warn -Title (T '不能删') -Text (Get-DeleteBlock $r.Detail -Leftover) | Out-Null; return }
        [void][FsTools]::Recycle($r.Detail, [long]$sync.Hwnd)
        $gone = -not (Test-Path -LiteralPath $r.Detail)
        OpLog '删除' (T '残留文件夹：移到回收站') $r.Detail $(if ($gone) { $r.Size } else { (T '没删掉，可能被占用') })
        if ($gone) { $script:startRows['leftover'].Remove($r) | Out-Null; Filter-StartRows; UI-Log ((T "残留文件夹已移到回收站：{0}") -f $r.Detail) }
        else { Show-Sheet -Kind warn -Title (T '没删掉') -Text (T '可能有程序正在用里面的文件。') | Out-Null }
        return
    }
    if ($r.Enabled) {
        $what = switch ($r.Kind) {
            'startup' { (T "「{0}」以后开机时不再自动启动。它本身不会被删，随时可以在这里重新启用，也可以在任务管理器的「启动应用」里改。") -f $r.Name }
            'task'    { (T "计划任务「{0}」会被禁用，到时间不再运行。随时可以在这里重新启用，也可以在「任务计划程序」里改。") -f $r.Name }
            default   { (T "「{0}」会从资源管理器的右键菜单里去掉（对新打开的窗口生效）。它所属的软件照常使用，随时可以在这里重新启用。") -f $r.Name }
        }
        if ((Show-Sheet -Title ((T "禁用「{0}」？") -f $r.Name) -Text $what -Buttons @((T '取消'), (T '禁用')) -Primary (T '禁用') -Cancel (T '取消')) -ne (T '禁用')) { return }
        Set-StartRow $r $false
    } else { Set-StartRow $r $true }
})
# ---------- 检查新版本（winget）----------
function Start-WingetCheck {
    if ($script:worker) { Show-Sheet -Title (T '请等当前操作做完') -Text (T '另一个操作还在进行中。') | Out-Null; return }
    if (-not (Get-WingetExe)) { Show-Sheet -Kind warn -Title (T '这台电脑没有 winget') -Text (T 'winget 是 Windows 自带的软件包管理器（「应用安装程序」），Windows 10 1809 以后的系统都有。打不开的话，在应用商店里搜「应用安装程序」装一下。') | Out-Null; return }
    $sync.Mode = 'winget'; $sync.WingetResult = $null
    Start-Op (T '用 winget 检查新版本') -NoCard; UI-Busy $true
    $ctl.AppsInfo.Text = (T '正在用 winget 查，要几十秒…')
    Start-Worker @'
$sync.WingetResult = Get-WingetUpgrades
'@ $null
}
function Apply-WingetResult($res) {
    if (-not $res) { return }
    if ($res.Err) {
        $msg = switch ($res.Err) { 'nowinget' { (T '这台电脑没有 winget') } 'timeout' { (T 'winget 三分钟都没查完，可能是网络不通') } default { $res.Err } }
        Show-Sheet -Kind warn -Title (T '没查成') -Text $msg | Out-Null; Filter-Apps; return
    }
    $items = @($res.Items)
    $hit = 0
    if ($script:appRows) {
        foreach ($r in $script:appRows) { $r.Upgrade = ''; $r.UpgradeId = '' }
        $norm = { param($x) (([string]$x).ToLowerInvariant() -replace '[^\p{L}\p{N}]', '') }
        foreach ($u in $items) {
            $un = & $norm $u.Name
            if ($un.Length -lt 2) { continue }
            foreach ($r in $script:appRows) {
                if ($r.Upgrade) { continue }
                $rn = & $norm $r.Name
                if ($rn -eq $un -or ($un.Length -ge 4 -and $rn.StartsWith($un)) -or ($rn.Length -ge 4 -and $un.StartsWith($rn))) {
                    $r.Upgrade = [string]$u.Available; $r.UpgradeId = [string]$u.Id
                    $r.Meta = ($r.Meta -replace '\s*·\s*' + [regex]::Escape((T '可升级到')) + '[^·]*', '') + ' · ' + (T '可升级到') + ' ' + $u.Available
                    $hit++; break
                }
            }
        }
    }
    $script:wingetItems = $items
    Filter-Apps
    if ($items.Count -eq 0) { Show-Sheet -Kind done -Title (T '都是最新的') -Text (T 'winget 没有查到有新版本的软件。') | Out-Null; return }
    $ctl.AppsInfo.Text = (T "winget：{0} 个软件有新版本，其中 {1} 个在列表里标出来了") -f $items.Count, $hit
    $lines = @($items | ForEach-Object { (T "{0}：{1} → {2}") -f $_.Name, $_.Version, $_.Available })
    $ans = Show-Sheet -Title ((T "{0} 个软件有新版本") -f $items.Count) -Text (T '列表里有的软件旁边多了「升级」按钮。也可以在终端窗口里一次全部升级：winget 会逐个下载安装，有的安装程序会弹出自己的窗口，照提示点就行。') -Items $lines `
        -Buttons @((T '好'), (T '在终端里全部升级')) -Primary (T '好') -Cancel (T '好')
    if ($ans -eq (T '在终端里全部升级')) { Start-WingetUpgrade '' }
}
function Start-WingetUpgrade([string]$id, [string]$name = '') {
    $exe = Get-WingetExe; if (-not $exe) { return }
    $cmd = if ($id) { ('"{0}" upgrade --id "{1}" --accept-source-agreements --accept-package-agreements' -f $exe, $id) }
           elseif ($name) { ('"{0}" upgrade --name "{1}" --accept-source-agreements --accept-package-agreements' -f $exe, $name) }
           else { ('"{0}" upgrade --all --accept-source-agreements --accept-package-agreements' -f $exe) }
    try {
        Start-Process -FilePath "$env:SystemRoot\System32\cmd.exe" -ArgumentList ('/k ' + $cmd)
        OpLog '系统设置' (T '用 winget 升级软件') $(if ($id) { $id } elseif ($name) { $name } else { (T '全部') }) $cmd
        UI-Log ((T "已在终端里开始升级：{0}") -f $cmd)
    } catch { Show-Sheet -Kind warn -Title (T '打不开终端') -Text $_.Exception.Message | Out-Null }
}
$ctl.BtnAppsUpdates.Add_Click({ Start-WingetCheck })

# ------------------------------------------------------------
# 自动提醒：用 Windows 任务计划，开关打开时创建，关掉时删除
# ------------------------------------------------------------
$script:taskRemind = 'CleanC\LowSpaceReminder'
$script:taskClean  = 'CleanC\WeeklyCleanup'
function Test-CleanTask([string]$name) { & "$env:SystemRoot\System32\schtasks.exe" /Query /TN $name 2>$null | Out-Null; return ($LASTEXITCODE -eq 0) }
function Get-TaskCommand([string]$name) {
    try { $x = [xml]((& "$env:SystemRoot\System32\schtasks.exe" /Query /TN $name /XML 2>$null) -join "`n"); return [string]$x.Task.Actions.Exec.Command } catch { return '' }
}
# 是不是在临时文件夹里（从压缩包里直接打开时，exe 会被解到这里，过后会被清掉）
function Test-TempPath([string]$path) {
    foreach ($t in @($env:TEMP, $env:TMP, "$env:LOCALAPPDATA\Temp", "$env:SystemRoot\Temp")) {
        if ($t -and $path.StartsWith($t.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase)) { return $true }
    }
    return $false
}
function Get-ExeVersion([string]$path) { try { return [version]([Diagnostics.FileVersionInfo]::GetVersionInfo($path).FileVersion) } catch { return $null } }
function Register-CleanTask([string]$name, [string]$desc, [string]$argsText, [string]$trigger) {
    $exe = [string]$env:CLEANC_SELF
    if (-not $exe -or -not (Test-Path -LiteralPath $exe)) { return (T '只有 exe 版本支持定时任务') }
    if (Test-TempPath $exe) { return ((T "本工具现在是从临时文件夹运行的（{0}），比如直接在压缩包里双击打开的。这个位置过后会被清掉，任务就找不到本工具了。`n`n请先把本工具复制到一个固定的位置（比如 D:\工具），从那里打开，再开启。") -f $exe) }
    $sid = [Security.Principal.WindowsIdentity]::GetCurrent().User.Value
    $esc = [Security.SecurityElement]
    $xml = @"
<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <RegistrationInfo><Author>腾挪 ClearC</Author><Description>$($esc::Escape($desc))</Description></RegistrationInfo>
  <Triggers>$($trigger.Replace('{USER}', $esc::Escape([Security.Principal.WindowsIdentity]::GetCurrent().Name)))</Triggers>
  <Principals><Principal id="Author"><UserId>$sid</UserId><LogonType>InteractiveToken</LogonType><RunLevel>HighestAvailable</RunLevel></Principal></Principals>
  <Settings>
    <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>
    <DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries>
    <StopIfGoingOnBatteries>false</StopIfGoingOnBatteries>
    <StartWhenAvailable>true</StartWhenAvailable>
    <ExecutionTimeLimit>PT1H</ExecutionTimeLimit>
    <Enabled>true</Enabled>
  </Settings>
  <Actions Context="Author"><Exec><Command>$($esc::Escape($exe))</Command><Arguments>$argsText</Arguments></Exec></Actions>
</Task>
"@
    $tmp = Join-Path $env:TEMP ("cleanc-task-{0}.xml" -f (Get-Random))
    [IO.File]::WriteAllText($tmp, $xml, [Text.Encoding]::Unicode)
    $out = & "$env:SystemRoot\System32\schtasks.exe" /Create /TN $name /XML $tmp /F 2>&1 | Out-String
    $code = $LASTEXITCODE
    Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
    if ($code -ne 0) { return $out.Trim() }
    return ''
}
# 两个任务的内容。提醒任务有两个触发时间：每次登录电脑 2 分钟后、每天中午 12 点（错过了就在下次开机后补一次）
function Enable-AutoTask([bool]$isRemind) {
    if ($isRemind) {
        return (Register-CleanTask $script:taskRemind (T '腾挪 ClearC：每次登录电脑后和每天中午各检查一次 C 盘剩余空间，低于设定值时提醒（每天最多一次）。在工具的「自动提醒」页关掉开关即可删除本任务。') '/check' `
            ('<LogonTrigger><UserId>{USER}</UserId><Delay>PT2M</Delay></LogonTrigger>' +
             '<CalendarTrigger><StartBoundary>2026-01-01T12:00:00</StartBoundary><ScheduleByDay><DaysInterval>1</DaysInterval></ScheduleByDay></CalendarTrigger>'))
    }
    $when = Get-Setting 'CleanWhen' 'sun'
    $days = @{ sun = 'Sunday'; mon = 'Monday'; tue = 'Tuesday'; wed = 'Wednesday'; thu = 'Thursday'; fri = 'Friday'; sat = 'Saturday' }
    $trig = if ($when -eq 'daily') { '<CalendarTrigger><StartBoundary>2026-01-04T12:30:00</StartBoundary><ScheduleByDay><DaysInterval>1</DaysInterval></ScheduleByDay></CalendarTrigger>' }
            else { $d = $days[$when]; if (-not $d) { $d = 'Sunday' }; "<CalendarTrigger><StartBoundary>2026-01-04T12:30:00</StartBoundary><ScheduleByWeek><DaysOfWeek><$d/></DaysOfWeek><WeeksInterval>1</WeeksInterval></ScheduleByWeek></CalendarTrigger>" }
    return (Register-CleanTask $script:taskClean (T '腾挪 ClearC：定期自动清理临时文件、缓存和日志（不搬家、不清空回收站、不碰个人文件夹）。在工具的「自动提醒」页关掉开关即可删除本任务。') '/autoclean' $trig)
}
# 打开工具时检查一次：本工具挪了位置、或者任务是旧版本建的（提醒没有「登录后检查」），就按现在的位置和设置重建
function Repair-AutoTasks {
    $exe = [string]$env:CLEANC_SELF
    if (-not $exe -or -not (Test-Path -LiteralPath $exe) -or (Test-TempPath $exe)) { return }
    $myVer = Get-ExeVersion $exe
    foreach ($isRemind in @($true, $false)) {
        $tn = if ($isRemind) { $script:taskRemind } else { $script:taskClean }
        $x = $null
        try { $raw = (& "$env:SystemRoot\System32\schtasks.exe" /Query /TN $tn /XML 2>$null) -join "`n"; if ($LASTEXITCODE -eq 0 -and $raw) { $x = [xml]$raw } } catch {}
        if (-not $x) { continue }
        $cmd = [string]$x.Task.Actions.Exec.Command
        $noLogon = $isRemind -and -not $x.Task.Triggers.LogonTrigger
        $repoint = $false
        if ($cmd -and $cmd -ine $exe) {
            # 只在原来那个 exe 不在了、或者比现在这个旧的时候才改用现在这个，别的副本（比如下载文件夹里的另一份）不抢
            $oldExists = Test-Path -LiteralPath $cmd
            $oldVer = if ($oldExists) { Get-ExeVersion $cmd } else { $null }
            $repoint = (-not $oldExists) -or ($myVer -and $oldVer -and $myVer -gt $oldVer)
        }
        if ($repoint -or ($noLogon -and $cmd -ieq $exe)) {
            $err = Enable-AutoTask $isRemind
            if (-not $err) { OpLog '系统设置' (T '更新任务计划') $tn $(if ($repoint) { ((T "改用 {0}（原来的 {1} 不在了或版本更旧）") -f $exe, $cmd) } else { (T '加上「登录电脑后检查」') }) }
        }
    }
}
function Remove-CleanTask([string]$name) { & "$env:SystemRoot\System32\schtasks.exe" /Delete /TN $name /F 2>$null | Out-Null }
$script:autoSync = $false
function Load-Auto {
    $script:autoSync = $true
    $exe = [string]$env:CLEANC_SELF
    $hasExe = $exe -and (Test-Path -LiteralPath $exe)
    $r1 = Test-CleanTask $script:taskRemind; $r2 = Test-CleanTask $script:taskClean
    $ctl.AutoRemindOn.IsChecked = $r1; $ctl.AutoCleanOn.IsChecked = $r2
    $ctl.AutoRemindOn.IsEnabled = $hasExe; $ctl.AutoCleanOn.IsEnabled = $hasExe
    $gb = Get-Setting 'RemindGB' '20'
    $idx = [array]::IndexOf(@('10', '20', '30', '50'), $gb); if ($idx -lt 0) { $idx = 1 }
    $ctl.AutoRemindGB.SelectedIndex = $idx
    $idx = [array]::IndexOf(@('0', '1', '2', '5', '10'), (Get-Setting 'JunkGB' '0')); if ($idx -lt 0) { $idx = 0 }
    $ctl.AutoJunkGB.SelectedIndex = $idx
    $idx = [array]::IndexOf(@('sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'daily'), (Get-Setting 'CleanWhen' 'sun')); if ($idx -lt 0) { $idx = 0 }
    $ctl.AutoCleanWhen.SelectedIndex = $idx
    $where = (T "不用开着本工具，也不用设置开机启动。开启后会在 Windows「任务计划程序」里建一个任务（{0}）：每次登录电脑 2 分钟后、以及每天中午 12 点，Windows 会在后台运行一下本工具（{1}）检查 C 盘，空间够就什么都不显示，查完马上退出。关掉开关就删除这个任务。`n请把本工具放在固定的位置，不要删掉；挪了位置后打开一次，任务会自动改用新位置。")
    $ctl.AutoRemindNote.Text = if ($hasExe) { $where -f $script:taskRemind, $exe } else { (T '只有 exe 版本支持自动提醒。') }
    $moved = ''
    foreach ($t in @($script:taskRemind, $script:taskClean)) { if (Test-CleanTask $t) { $c = Get-TaskCommand $t; if ($c -and $hasExe -and ($c -ine $exe)) { $moved = (T '本工具的位置变了，请把开关关掉再打开一次，让任务改用现在的位置。') } } }
    if ($moved) { $ctl.AutoRemindNote.Text += "`n" + $moved }
    $last = ''
    foreach ($row in (Read-OpLog)) { if ($row.What -in @('每周自动清理完成', (T '每周自动清理完成'))) { $last = (T "上次自动清理：{0}，{1}") -f $row.Time, $row.Detail; break } }
    $ctl.AutoCleanNote.Text = if ($hasExe) { ((T "任务名：{0}。") -f $script:taskClean) + $(if ($last) { "`n$last" } else { '' }) } else { (T '只有 exe 版本支持每周自动清理。') }
    $ctl.AutoCleanNote.Text += "`n" + $(if (Get-StorageSenseOn) { (T 'Windows 自带的「存储感知」现在是开着的：它也会定期清临时文件和回收站，和这里的自动清理不冲突，只是会各做一遍。') } else { (T 'Windows 自带的「存储感知」现在是关着的（在 Windows 设置 → 系统 → 存储里）。') })
    $script:autoSync = $false
    Draw-History
}
function Draw-History {
    $h = Get-History
    $days = [ordered]@{}
    foreach ($x in $h) { $days[$x.When.ToString('yyyy-MM-dd')] = $x }
    $keys = @($days.Keys | Select-Object -Last 30)
    $bars = New-Object System.Collections.Generic.List[HistBar]
    foreach ($k in $keys) {
        $x = $days[$k]
        $used = [math]::Max([double]0, $x.Total - $x.Free); $ratio = if ($x.Total -gt 0) { $used / $x.Total } else { 0 }
        $b = New-Object HistBar
        $b.H = [math]::Max([double]3, 140.0 * $ratio)
        $b.Fill = if ($ratio -ge 0.95) { '#FF3B30' } elseif ($ratio -ge 0.85) { '#FF9F0A' } else { '#0071E3' }
        $b.Tip = (T "{0}：已用 {1}，剩余 {2}") -f $k, (Fmt $used), (Fmt $x.Free)
        $b.Label = $k
        $bars.Add($b)
    }
    $ctl.HistChart.ItemsSource = $bars
    if ($keys.Count -gt 0) {
        $f = $days[$keys[0]]; $l = $days[$keys[-1]]
        $ctl.HistFirst.Text = $keys[0]; $ctl.HistLast.Text = $keys[-1]
        $d = $l.Free - $f.Free
        $ctl.HistInfo.Text = (T "最近 {0} 天有记录：C 盘剩余从 {1} 变成 {2}（{3}{4}）。蓝色正常，橙色表示用掉了八成五以上，红色表示快满了。") -f $keys.Count, (Fmt $f.Free), (Fmt $l.Free), $(if ($d -ge 0) { (T '多了 ') } else { (T '少了 ') }), (Fmt ([math]::Abs($d)))
    } else { $ctl.HistInfo.Text = (T '还没有记录。每次打开本工具都会记一笔。'); $ctl.HistFirst.Text = ''; $ctl.HistLast.Text = '' }
}
$ctl.AutoRemindGB.Add_SelectionChanged({
    if ($script:autoSync) { return }
    $gb = @('10', '20', '30', '50')[[math]::Max(0, $ctl.AutoRemindGB.SelectedIndex)]
    Set-Setting 'RemindGB' $gb
    OpLog '系统设置' (T '空间不足提醒的界限') "$gb GB" ''
})
$ctl.AutoJunkGB.Add_SelectionChanged({
    if ($script:autoSync) { return }
    $gb = @('0', '1', '2', '5', '10')[[math]::Max(0, $ctl.AutoJunkGB.SelectedIndex)]
    Set-Setting 'JunkGB' $gb
    OpLog '系统设置' (T '可清理垃圾提醒的界限') $(if ($gb -eq '0') { (T '不提醒') } else { "$gb GB" }) ''
})
# 换了清理的时间：任务开着就按新时间重建
$ctl.AutoCleanWhen.Add_SelectionChanged({
    if ($script:autoSync) { return }
    $w = @('sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'daily')[[math]::Max(0, $ctl.AutoCleanWhen.SelectedIndex)]
    Set-Setting 'CleanWhen' $w
    OpLog '系统设置' (T '自动清理的时间') ([string]$ctl.AutoCleanWhen.SelectedItem.Content) ''
    if (Test-CleanTask $script:taskClean) { $err = Enable-AutoTask $false; if ($err) { Show-Sheet -Kind warn -Title (T '没改成') -Text $err | Out-Null }; Load-Auto }
})
foreach ($sw in @($ctl.AutoRemindOn, $ctl.AutoCleanOn)) {
    $sw.Add_Checked({
        if ($script:autoSync) { return }
        $isRemind = [object]::ReferenceEquals($this, $ctl.AutoRemindOn)
        $err = Enable-AutoTask $isRemind
        if ($isRemind) { $what = (T '开启空间不足提醒'); $tn = $script:taskRemind } else { $what = (T '开启每周自动清理'); $tn = $script:taskClean }
        if ($err) { Show-Sheet -Kind warn -Title (T '没开成') -Text $err | Out-Null; Load-Auto; return }
        OpLog '系统设置' $what $tn ((T "任务计划：{0}") -f [string]$env:CLEANC_SELF)
        Load-Auto
    })
    $sw.Add_Unchecked({
        if ($script:autoSync) { return }
        $isRemind = [object]::ReferenceEquals($this, $ctl.AutoRemindOn)
        $tn = if ($isRemind) { $script:taskRemind } else { $script:taskClean }
        Remove-CleanTask $tn
        OpLog '系统设置' $(if ($isRemind) { (T '关闭空间不足提醒') } else { (T '关闭每周自动清理') }) $tn (T '已删除任务计划')
        Load-Auto
    })
}

# ------------------------------------------------------------
# 操作日志
# ------------------------------------------------------------
$script:logCatLook = @{
    '删除' = @('#FDECEE', '#D70015'); '搬运' = @('#E8F1FC', '#0062C4'); '合并' = @('#E6F4EA', '#1E7B34'); '压缩' = @('#F3EAFD', '#7A3FC2')
    '卸载' = @('#FFF1E6', '#B25000'); '系统设置' = @('#EFEFF4', '#3A3A3C'); '日志' = @('#EFEFF4', '#6E6E73')
}
function Read-OpLog {
    $rows = New-Object System.Collections.Generic.List[LogRow]
    if (-not (Test-Path -LiteralPath $script:opLogDir)) { return ,$rows }
    $inv = [Globalization.CultureInfo]::InvariantCulture
    foreach ($f in @(Get-ChildItem -LiteralPath $script:opLogDir -Filter '操作日志-*.txt' -File -ErrorAction SilentlyContinue | Sort-Object Name -Descending)) {
        $lines = [IO.File]::ReadAllLines($f.FullName, [Text.Encoding]::UTF8)
        for ($i = $lines.Count - 1; $i -ge 0; $i--) {
            $l = $lines[$i]
            if (-not $l -or $l.StartsWith('#')) { continue }
            $a = $l.Split("`t")
            if ($a.Count -lt 3) { continue }
            $t = [datetime]::MinValue
            [void][datetime]::TryParseExact($a[0], 'yyyy-MM-dd HH:mm:ss', $inv, 'None', [ref]$t)
            $r = New-Object LogRow
            $r.Time = $a[0]; $r.When = $t; $r.Cat = $a[1]; $r.CatText = T $a[1]; $r.What = $a[2]
            $r.Target = if ($a.Count -gt 3) { $a[3] } else { '' }
            $r.Detail = if ($a.Count -gt 4) { $a[4] } else { '' }
            $lk = $script:logCatLook[$r.Cat]; if (-not $lk) { $lk = @('#EFEFF4', '#6E6E73') }
            $r.CatBg = $lk[0]; $r.CatFg = $lk[1]
            $rows.Add($r)
        }
    }
    return ,$rows
}
$script:logAll = $null
function Selected-Tag($panel) { foreach ($c in $panel.Children) { if ($c.IsChecked) { return [string]$c.Tag } }; return '' }
function Filter-Log {
    if ($null -eq $script:logAll) { return }
    $cat = Selected-Tag $ctl.LogCats
    $days = [int](Selected-Tag $ctl.LogRange)
    $since = if ($days -gt 0) { (Get-Date).AddDays(-$days) } else { [datetime]::MinValue }
    $q = ([string]$ctl.LogSearch.Text).Trim()
    $col = New-Object System.Collections.Generic.List[LogRow]
    foreach ($r in $script:logAll) {
        if ($cat -and $r.Cat -ne $cat) { continue }
        if ($r.When -lt $since) { continue }
        if ($q -and ($r.What + ' ' + $r.Target + ' ' + $r.Detail).IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -lt 0) { continue }
        $col.Add($r)
    }
    $ctl.LogList.ItemsSource = $col
    $ctl.LogCount.Text = (T "{0:N0} 条") -f $col.Count
    $ctl.EmptyLog.Visibility = if ($col.Count -gt 0) { 'Collapsed' } else { 'Visible' }
    $ctl.EmptyLogText.Text = if ($script:logAll.Count -eq 0) { (T '还没有操作记录。删除、搬运等操作做完后会出现在这里') } else { (T '没有符合条件的记录') }
}
$script:logKeepSync = $false
function Update-LogKeepNote {
    $m = Get-LogMonths
    $keepText = switch ($m) { 0 { (T '永久保存') } 1 { (T '1 个月') } 3 { (T '3 个月') } 6 { (T '半年') } 12 { (T '1 年') } 24 { (T '2 年') } default { ((T "{0} 个月") -f $m) } }
    $cut = (Get-Date).Date.AddMonths(-$m)
    $lines = @(
        ((T "·  日志是普通的 txt 文件，放在 {0}，每个月一个，可以用记事本直接打开。") -f $script:opLogDir)
        (T '·  删除、搬运、合并、压缩、卸载和系统设置的每一次改动都会记下来：什么时间、做了什么、对哪个文件或文件夹、结果怎样。只记操作，不保存文件内容。')
    )
    if ($m -gt 0) { $lines += ((T "·  当前保存 {0}：每次打开本工具时，会自动删除 {1:yyyy-MM-dd}（{0}前）之前的记录，删掉后找不回来。") -f $keepText, $cut) }
    else { $lines += (T '·  当前设置为永久保存：记录不会自动删除，日志文件会越来越多（通常每月几十 KB 到几 MB）。') }
    $ctl.LogKeepNote.Text = $lines -join "`n"
}
function Load-Log {
    $script:logKeepSync = $true
    $m = Get-LogMonths
    for ($i = 0; $i -lt $ctl.LogKeep.Items.Count; $i++) { if ([string]$ctl.LogKeep.Items[$i].Tag -eq [string]$m) { $ctl.LogKeep.SelectedIndex = $i } }
    $script:logKeepSync = $false
    Update-LogKeepNote
    $script:logAll = Read-OpLog
    Filter-Log
}
foreach ($c in @($ctl.LogCats.Children) + @($ctl.LogRange.Children)) { $c.Add_Checked({ Filter-Log }) }
$ctl.LogSearch.Add_TextChanged({ Filter-Log })
$ctl.BtnLogRefresh.Add_Click({ Load-Log })
$ctl.BtnLogOpenDir.Add_Click({ New-Item -ItemType Directory -Path $script:opLogDir -Force | Out-Null; Open-Location $script:opLogDir })
$ctl.LogKeep.Add_SelectionChanged({
    if ($script:logKeepSync -or -not $ctl.LogKeep.SelectedItem) { return }
    $new = [int]$ctl.LogKeep.SelectedItem.Tag; $old = Get-LogMonths
    if ($new -eq $old) { return }
    if ($new -gt 0 -and ($old -eq 0 -or $new -lt $old)) {
        $cut = (Get-Date).Date.AddMonths(-$new)
        $ans = Show-Sheet -Kind warn -Title ((T "保存时间改成「{0}」？") -f $ctl.LogKeep.SelectedItem.Content) -Text ((T "{0:yyyy-MM-dd} 之前的操作记录会马上删除，删掉后找不回来。") -f $cut) -Buttons @((T '取消'), (T '改')) -Primary (T '改') -Cancel (T '取消')
        if ($ans -ne (T '改')) { Load-Log; return }
    }
    Set-Setting 'LogMonths' ([string]$new)
    OpLog '日志' (T '修改日志保存时间') ([string]$ctl.LogKeep.SelectedItem.Content) ''
    $n = Prune-OpLog $new
    if ($n -gt 0) { OpLog '日志' (T '删除超过保存时间的旧记录') '' ((T "{0} 条") -f $n) }
    Load-Log
})

# ------------------------------------------------------------
# 重复文件：合并为一份（硬链接）
# ------------------------------------------------------------
# 归档：不删，把勾选的搬到选定的文件夹（<文件夹>\<盘符>\<原路径>），每组照样至少留一份不动
$ctl.BtnDupMove.Add_Click({
    if ($script:worker) { return }
    $plan = New-Object System.Collections.ArrayList
    $allChecked = 0; $bytes = [double]0
    foreach ($gid in @($script:dupByGroup.Keys)) {
        $rows = @($script:dupByGroup[$gid])
        $del = @($rows | Where-Object { $_.ToDelete -and $_.CanDelete })
        if ($del.Count -eq 0) { continue }
        if ($del.Count -ge $rows.Count) { $allChecked++; continue }
        foreach ($r in $del) { [void]$plan.Add(@{ Path = $r.Path; Size = $r.Size }); $bytes += $r.Size }
    }
    if ($plan.Count -eq 0) { if ($allChecked) { Show-Sheet -Kind warn -Title (T '每组至少要留一份') -Text ((T "有 {0} 组把所有副本都勾上了，这些组不会动。") -f $allChecked) | Out-Null }; return }
    $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
    $dlg.Description = (T '把勾选的文件搬到哪个文件夹（里面会按盘符和原路径建子文件夹）')
    if ($dlg.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
    $dest = $dlg.SelectedPath.TrimEnd('\')
    $why = Get-DeleteBlock $dest
    if ($why) { Show-Sheet -Kind warn -Title (T '这个文件夹不能用来归档') -Text $why | Out-Null; return }
    $free = DriveFree ($dest.Substring(0, 2))
    if ($free -lt $bytes * 1.02) { Show-Sheet -Kind warn -Title ((T "{0} 盘放不下") -f $dest.Substring(0, 1)) -Text ((T "{0} 只剩 {1}，要搬的文件有 {2}。") -f $dest.Substring(0, 2), (GB $free), (GB $bytes)) | Out-Null; return }
    $text = (T "把 {0} 个勾选的文件搬到 {1}，共 {2}。不删任何东西：每个文件放到「{1}\盘符\原来的路径」，保留的那份留在原地。跨盘的会复制再删原件。`n`n归档以后这些文件就不在原来的位置了，用到它们的程序要重新指路径。") -f $plan.Count, $dest, (Fmt $bytes)
    if ($allChecked) { $text += ((T "`n`n另有 {0} 组所有副本都被勾选，这些组会跳过。") -f $allChecked) }
    if ((Show-Sheet -Title ((T "归档 {0} 个文件？") -f $plan.Count) -Text $text -Buttons @((T '取消'), (T '归档')) -Primary (T '归档') -Cancel (T '取消')) -ne (T '归档')) { return }
    $sync.Mode = 'dupmove'; $sync.DupDeleted = $null; $sync.DupMoveDest = $dest
    Start-Op ((T "归档 {0} 个文件") -f $plan.Count)
    UI-Busy $true
    UI-Log ((T "开始归档 {0} 个文件到 {1}") -f $plan.Count, $dest)
    Start-Worker @'
$done = New-Object System.Collections.ArrayList
$i = 0; $total = $arg.Plan.Count; $moved = [double]0; $fails = 0
foreach ($p in $arg.Plan) {
    if (Stopping) { break }
    $i++
    SetP @{ Steps = $total; Step = $i; StepName = [IO.Path]::GetFileName($p.Path); SubKind = 'none' }
    if ($arg.Protect -and (Test-Personal $p.Path)) { Log ((T "  跳过（C 盘个人文件夹，受保护）：{0}") -f $($p.Path)); continue }
    $fi = Get-Item -LiteralPath $p.Path -Force -ErrorAction SilentlyContinue
    if (-not $fi) { continue }
    if ($fi.Length -ne $p.Size) { Log ((T "  跳过（文件在扫描后被修改过）：{0}") -f $($p.Path)); continue }
    $rel = $p.Path.Substring(0, 1).ToUpper() + '\' + $p.Path.Substring(3)
    $to = Join-Path $arg.Dest $rel
    if ($to.StartsWith($p.Path + '\', [StringComparison]::OrdinalIgnoreCase) -or $to -ieq $p.Path) { Log ((T "  跳过（目标在原文件里面）：{0}") -f $($p.Path)); continue }
    try {
        New-Item -ItemType Directory -Path (Split-Path $to -Parent) -Force | Out-Null
        if (Test-Path -LiteralPath $to) { $to = Join-Path (Split-Path $to -Parent) (([IO.Path]::GetFileNameWithoutExtension($to)) + ' (' + (Get-Date -Format 'yyyyMMdd-HHmmss') + ')' + [IO.Path]::GetExtension($to)) }
        [IO.File]::Move($p.Path, $to)
        if (-not (Test-Path -LiteralPath $to) -or (Get-Item -LiteralPath $to).Length -ne $p.Size) { throw (T '搬过去的文件大小对不上') }
        [void]$done.Add($p.Path); $moved += $p.Size
        OpLog '搬运' (T '归档重复文件') $p.Path $to
        if ($total -le 200 -or $i % 100 -eq 0) { Log ((T "  [{0}/{1}] 已归档  {2}") -f $i, $total, $p.Path) }
    } catch { $fails++; Log ((T "  归档失败  {0}：{1}") -f $($p.Path), $($_.Exception.Message)) }
}
Log ((T "归档完成：{0} 个文件，{1}；失败 {2} 个。") -f $done.Count, (Fmt $moved), $fails)
$sync.DupDeleted = $done
'@ @{ Plan = $plan; Dest = $dest; Protect = [bool]$ctl.DupProtect.IsChecked }
})
$ctl.BtnDupMerge.Add_Click({
    if ($script:worker) { return }
    if ($script:dupSimilar) { Show-Sheet -Kind warn -Title (T '相似照片不能合并') -Text (T '合并是把内容完全相同的文件换成硬链接；相似照片内容不同，合并会丢掉其中一张。') | Out-Null; return }
    $plan = New-Object System.Collections.ArrayList
    $skip = 0; $bytes = [double]0
    foreach ($gid in @($script:dupByGroup.Keys)) {
        $rows = @($script:dupByGroup[$gid])
        $del = @($rows | Where-Object { $_.ToDelete -and $_.CanDelete })
        $keepers = @($rows | Where-Object { -not $_.ToDelete })
        if ($del.Count -eq 0 -or $keepers.Count -eq 0) { if ($del.Count) { $skip += $del.Count }; continue }
        foreach ($r in $del) {
            $root = [IO.Path]::GetPathRoot($r.Path)
            $k = @($keepers | Where-Object { [IO.Path]::GetPathRoot($_.Path) -ieq $root }) | Select-Object -First 1
            if (-not $k) { $skip++; continue }
            [void]$plan.Add(@{ Path = $r.Path; Size = $r.Size; Keep = $k.Path; Verified = $r.Verified })
            $bytes += $r.Size
        }
    }
    if ($plan.Count -eq 0) {
        Show-Sheet -Title (T '没有可以合并的') -Text (T '合并只适用于同一块盘上的副本：勾选的副本要和没勾选（保留）的那份在同一块盘上。') | Out-Null
        return
    }
    $text = (T "合并后，每个位置的文件都还在，打开、复制都和原来一样，只是这几个位置共用一份空间。`n`n要注意：合并后它们其实是同一个文件，改了其中一个位置，其他位置也会跟着变。所以适合照片、视频、安装包、压缩包这类不会再改的文件。")
    if ($skip -gt 0) { $text += ((T "`n`n另有 {0} 个勾选的副本和保留的那份不在同一块盘上，不能合并，会跳过。") -f $skip) }
    $ans = Show-Sheet -Title ((T "合并 {0} 个重复文件，腾出 {1}？") -f $plan.Count, (Fmt $bytes)) -Text $text -Confirm (T '我知道合并后改动一个位置，其他位置会跟着变。') -Buttons @((T '取消'), (T '合并')) -Primary (T '合并') -Cancel (T '取消')
    if ($ans -ne (T '合并')) { return }
    $sync.Mode = 'merge'; $sync.DupMerged = $null
    Start-Op ((T "合并 {0} 个重复文件") -f $plan.Count)
    UI-Busy $true
    Start-Worker @'
$done = New-Object System.Collections.ArrayList
$i = 0; $total = $arg.Plan.Count
foreach ($p in $arg.Plan) {
    if (Stopping) { break }
    $i++
    SetP @{ Steps = $total; Step = $i; StepName = [IO.Path]::GetFileName($p.Path); SubKind = 'none' }
    if ($arg.Protect -and (Test-Personal $p.Path)) { continue }
    $fi = Get-Item -LiteralPath $p.Path -Force -ErrorAction SilentlyContinue
    $ki = Get-Item -LiteralPath $p.Keep -Force -ErrorAction SilentlyContinue
    if (-not $fi -or -not $ki -or $fi.Length -ne $p.Size -or $ki.Length -ne $p.Size) { Log ((T "  跳过（文件在扫描后变了）：{0}") -f $($p.Path)); continue }
    if (-not $p.Verified) {
        SetP @{ SubKind = 'verify'; Detail = $p.Path }
        $same = [DupFinder]::SameContent($p.Keep, $p.Path)
        if (-not $same -and (Stopping)) { break }   # 核对到一半取消了：这个不合并
        if (-not $same) { Log ((T "  跳过（和保留的那份内容不完全相同）：{0}") -f $($p.Path)); SetP @{ SubKind = 'none' }; continue }
        SetP @{ SubKind = 'none' }
    }
    $err = [FsTools]::MergeHardLink($p.Keep, $p.Path)
    if ($err) { Log ((T "  没合并：{0}：{1}") -f $($p.Path), $err); OpLog '合并' (T '合并为一份失败') $p.Path $err; continue }
    [void]$done.Add($p.Path)
    OpLog '合并' (T '合并为一份（硬链接）') $p.Path ((T "和 {0} 共用一份，腾出 {1}") -f $p.Keep, (GB $p.Size))
}
$sync.DupMerged = $done
'@ @{ Plan = $plan; Protect = [bool]$ctl.DupProtect.IsChecked }
})

# ------------------------------------------------------------
# 设置：外观、语言、显示哪些内容
# ------------------------------------------------------------
# 可以关掉的页面、左下角的按钮：设置里存关掉了的，逗号隔开
$script:optPages = [ordered]@{ dup = 'SetPageDup'; save = 'SetPageSave'; apps = 'SetPageApps'; health = 'SetPageHealth'; moves = 'SetPageMoves'; auto = 'SetPageAuto'; log = 'SetPageLog' }
$script:optLinks = [ordered]@{ theme = @('SetLinkTheme', 'BtnTheme'); lang = @('SetLinkLang', 'BtnLang'); feedback = @('SetLinkFeedback', 'BtnFeedback'); log = @('SetLinkLog', 'BtnLog') }
# 开关：设置里的名字 → 设置页上的开关（默认都开）
$script:optSwitches = [ordered]@{ PageSub = 'SetPageSub'; MapCheck = 'SetMapCheck'; MapBar = 'SetMapBar'; MapPct = 'SetMapPct'; MapMeta = 'SetMapMeta'; MapDisk = 'SetMapDisk'; MapFastBtn = 'SetMapFastBtn'; MapHealth = 'SetMapHealth' }
function Get-Flag([string]$k) { (Get-Setting $k '1') -ne '0' }
function Get-HiddenSet([string]$k) { $h = @{}; foreach ($x in ((Get-Setting $k '') -split ',')) { $x = $x.Trim(); if ($x) { $h[$x] = $true } }; return $h }
# 三种模式各显示什么：页面、左下角按钮、各页里的高级功能。换模式只改显示，不丢设置
$script:pageLvl = @{ dup = 1; moves = 1; auto = 1; log = 1 }
$script:linkLvl = @{ log = 2 }
$script:appsUpdatesAllowed = $true
function Get-ModeName([int]$m = (Get-Mode)) { switch ($m) { 0 { (T '普通用户') } 1 { (T '工程师') } default { (T '开发者和 IT') } } }
function Apply-Mode {
    $m = Get-Mode
    $v = { param([int]$need) if ($m -ge $need) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed } }
    # 空间地图：找文件、和上次比、导出、压缩是工程师的；快速扫描开关、空间明细是开发者的
    foreach ($n in 'MapViewFiles', 'MapViewGrow', 'MapViewRecent', 'BtnMapExport', 'BtnMapReport', 'BtnMapCompress') { $ctl[$n].Visibility = & $v 1 }
    if ($m -lt 1 -and -not $ctl.MapViewDirs.IsChecked -and -not $ctl.MapViewTree.IsChecked -and -not $ctl.MapViewTypes.IsChecked) { $ctl.MapViewDirs.IsChecked = $true }
    # 省空间
    foreach ($n in 'SaveCardPf', 'SaveCardRp', 'SaveCardFc', 'SaveCardVd', 'SaveCardMerge') { $ctl[$n].Visibility = & $v 1 }
    foreach ($n in 'SaveCardRs', 'SaveCardCs', 'SaveCardDump', 'SaveCardTmp') { $ctl[$n].Visibility = & $v 2 }
    # 软件管理
    $ctl.AppsViewBox.Visibility = & $v 1
    foreach ($n in 'AppsViewStartup', 'AppsViewLeft') { $ctl[$n].Visibility = & $v 1 }
    foreach ($n in 'AppsViewTasks', 'AppsViewMenu') { $ctl[$n].Visibility = & $v 2 }
    if (($m -lt 1 -and -not $ctl.AppsViewApps.IsChecked) -or ($m -lt 2 -and ($ctl.AppsViewTasks.IsChecked -or $ctl.AppsViewMenu.IsChecked))) { $ctl.AppsViewApps.IsChecked = $true }
    $win.Resources['AppMoveVis'] = & $v 1
    $script:appsUpdatesAllowed = ($m -ge 1)
    if ($ctl.BtnAppsUpdates.Visibility -eq 'Visible' -and $m -lt 1) { $ctl.BtnAppsUpdates.Visibility = 'Collapsed' }
    # 清理页、自动提醒、帮助、设置
    $ctl.BtnCleanCustom.Visibility = & $v 2
    $ctl.AutoJunkRow.Visibility = & $v 1
    foreach ($n in 'HealthCardBoot', 'HealthCardCrash', 'HealthCardMon') { $ctl[$n].Visibility = & $v 1 }
    $ctl.BtnSfcRepair.Visibility = & $v 2; $ctl.HealthCardEvents.Visibility = & $v 2
    $ctl.FbCopyDiag.Visibility = & $v 1; $ctl.FbSelfTest.Visibility = & $v 2
    $ctl.SetCardDisplay.Visibility = & $v 1; $ctl.SetCardScan.Visibility = & $v 2
    foreach ($n in 'SetCustomList', 'SetCustomEmpty', 'BtnSetCustomAdd', 'SetExcludeList', 'SetExcludeEmpty', 'BtnSetExcludeAdd', 'SetCustomHead', 'SetCustomNote', 'SetExcludeHead', 'SetExcludeNote') { $ctl[$n].Visibility = & $v 2 }
    $ctl.ModeTag.Text = (Get-ModeName $m) + (T '模式')
    $ctl.SetModeNote.Text = switch ($m) {
        0 { (T '普通用户：清理 C 盘、省空间、空间地图、软件管理、帮助。清理列表里只有常见的缓存和临时文件，删了都会自动重建；有代价的项目仍然默认跳过。') }
        1 { (T '工程师：再加上重复文件、搬家管理、自动提醒、操作日志；空间地图的找文件、和上次比、最近改动、导出；省空间的页面文件、还原点、压缩文件夹、虚拟磁盘；软件管理的开机启动、残留文件夹、检查新版本和搬到其他盘；系统健康的开机用时、蓝屏诊断、活动监控；清理列表里多出开发工具的缓存。') }
        default { (T '开发者和 IT：全部功能。再加上计划任务、右键菜单、保留的存储、组件存储分析、蓝屏转储、临时文件夹位置、自定义清理列表和排除、快速扫描开关、空间明细、检查扫描功能、运行记录、修复系统文件、Windows 事件汇总，以及 Installer 孤儿安装包、事件日志、旧版驱动包、NuGet / Gradle / Maven / JetBrains 缓存这类项目。') }
    }
    $script:setLoading = $true
    try { $ctl.SetModeBasic.IsChecked = ($m -eq 0); $ctl.SetModePro.IsChecked = ($m -eq 1); $ctl.SetModeExpert.IsChecked = ($m -eq 2) } finally { $script:setLoading = $false }
    Apply-Display
    # 正在看的页面在这个模式下没有了：回到清理页
    if ($script:curPage -and $script:pageLvl.ContainsKey($script:curPage) -and $script:pageLvl[$script:curPage] -gt $m) { Show-Page 'clean' }
    if ($script:mapRoot) { try { $ctl.BtnMapAcct.Visibility = if ($script:mapRoot.HasDisk -and $m -ge 2) { 'Visible' } else { 'Collapsed' } } catch {} }
}
function Set-Mode([string]$mode) {
    Set-Setting 'Mode' $mode
    Apply-Mode
    OpLog '系统设置' (T '使用模式') (Get-ModeName) ''
    UI-Log ((T "使用模式：{0}") -f (Get-ModeName))
}
foreach ($rb in @($ctl.SetModeBasic, $ctl.SetModePro, $ctl.SetModeExpert)) {
    $rb.Add_Checked({
        if ($script:setLoading) { return }
        Set-Mode $(if ([object]::ReferenceEquals($this, $ctl.SetModeBasic)) { 'basic' } elseif ([object]::ReferenceEquals($this, $ctl.SetModePro)) { 'pro' } else { 'expert' })
    })
}
$ctl.ModeTag.Add_MouseLeftButtonUp({ Show-Page 'settings'; $ctl.SetScroll.ScrollToTop() })
function Apply-Display {
    $m = Get-Mode
    $vis = { param([bool]$on) if ($on) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed } }
    $win.Resources['SubVis'] = & $vis (Get-Flag 'PageSub')
    $win.Resources['MapCkVis'] = & $vis (Get-Flag 'MapCheck')
    $win.Resources['MapBarVis'] = & $vis (Get-Flag 'MapBar')
    $win.Resources['MapPctVis'] = & $vis (Get-Flag 'MapPct')
    $win.Resources['MapMetaVis'] = & $vis (Get-Flag 'MapMeta')
    $win.Resources['MapHealthVis'] = & $vis (Get-Flag 'MapHealth')
    $ctl.MapFast.Visibility = & $vis ((Get-Flag 'MapFastBtn') -and $m -ge 2)
    $hp = Get-HiddenSet 'HidePages'
    $show = @{}
    foreach ($k in $script:optPages.Keys) { $show[$k] = (-not $hp.ContainsKey($k)) -and (-not $script:pageLvl.ContainsKey($k) -or $script:pageLvl[$k] -le $m); $ctl[$script:pageList[$k][1]].Visibility = & $vis $show[$k] }
    $ctl.NavHeadManage.Visibility = & $vis ($show['moves'] -or $show['auto'] -or $show['log'])
    $hl = Get-HiddenSet 'HideLinks'
    foreach ($k in $script:optLinks.Keys) { $ctl[$script:optLinks[$k][1]].Visibility = & $vis ((-not $hl.ContainsKey($k)) -and (-not $script:linkLvl.ContainsKey($k) -or $script:linkLvl[$k] -le $m)) }
}
# 换了「实际占用和硬链接」这类要重新生成行的设置：当前这一层重新列一遍
function Refresh-MapRows {
    if (-not $script:mapRoot) { return }
    if ($script:mapView -eq 'files') { Show-MapFiles } elseif ($script:mapView -ne 'grow') { Show-MapLevel $(if ($script:mapCur) { $script:mapCur } else { $script:mapRoot }) }
}
$script:setLoading = $false
function Load-Settings {
    $script:setLoading = $true
    try {
        $ctl.SetThemeLight.IsChecked = ($script:themePref -eq 'light'); $ctl.SetThemeDark.IsChecked = ($script:themePref -eq 'dark'); $ctl.SetThemeSystem.IsChecked = ($script:themePref -eq 'system')
        $ctl.SetLangZh.IsChecked = ($script:Lang -ne 'en'); $ctl.SetLangEn.IsChecked = ($script:Lang -eq 'en')
        $hp = Get-HiddenSet 'HidePages'; foreach ($k in $script:optPages.Keys) { $ctl[$script:optPages[$k]].IsChecked = -not $hp.ContainsKey($k) }
        $hl = Get-HiddenSet 'HideLinks'; foreach ($k in $script:optLinks.Keys) { $ctl[$script:optLinks[$k][0]].IsChecked = -not $hl.ContainsKey($k) }
        foreach ($k in $script:optSwitches.Keys) { $ctl[$script:optSwitches[$k]].IsChecked = Get-Flag $k }
        $ctl.SetFast.IsChecked = [bool]$ctl.MapFast.IsChecked
        $ctl.SetLowIo.IsChecked = ((Get-Setting 'LowIo' '0') -eq '1')
        $ctl.SetRecycle.IsChecked = ((Get-Setting 'Recycle' '0') -eq '1')
    } finally { $script:setLoading = $false }
}
function Save-Display {
    Set-Setting 'HidePages' ((@($script:optPages.Keys | Where-Object { -not $ctl[$script:optPages[$_]].IsChecked })) -join ',')
    Set-Setting 'HideLinks' ((@($script:optLinks.Keys | Where-Object { -not $ctl[$script:optLinks[$_][0]].IsChecked })) -join ',')
    foreach ($k in $script:optSwitches.Keys) { Set-Setting $k $(if ($ctl[$script:optSwitches[$k]].IsChecked) { '1' } else { '0' }) }
    Apply-Display
}
foreach ($k in $script:optPages.Keys) { $ctl[$script:optPages[$k]].Add_Click({ if (-not $script:setLoading) { Save-Display } }) }
foreach ($k in $script:optLinks.Keys) { $ctl[$script:optLinks[$k][0]].Add_Click({ if (-not $script:setLoading) { Save-Display } }) }
foreach ($k in $script:optSwitches.Keys) { $ctl[$script:optSwitches[$k]].Add_Click({ if (-not $script:setLoading) { Save-Display; if ([object]::ReferenceEquals($this, $ctl.SetMapDisk)) { Refresh-MapRows } } }) }
$ctl.SetFast.Add_Click({ if (-not $script:setLoading) { Set-FastScan ([bool]$ctl.SetFast.IsChecked) } })
[DupFinder]::LowPriority = ((Get-Setting 'LowIo' '0') -eq '1')
$ctl.SetRecycle.Add_Click({
    if ($script:setLoading) { return }
    $on = [bool]$ctl.SetRecycle.IsChecked
    Set-Setting 'Recycle' $(if ($on) { '1' } else { '0' })
    UI-Log $(if ($on) { (T '删除时先放进回收站：已打开') } else { (T '删除时先放进回收站：已关闭') })
})
$ctl.SetLowIo.Add_Click({
    if ($script:setLoading) { return }
    $on = [bool]$ctl.SetLowIo.IsChecked
    Set-Setting 'LowIo' $(if ($on) { '1' } else { '0' }); [DupFinder]::LowPriority = $on
    UI-Log $(if ($on) { (T '查重复文件时让着其他程序：已打开') } else { (T '查重复文件时让着其他程序：已关闭') })
})
$ctl.BtnSetReset.Add_Click({
    Set-Setting 'HidePages' ''; Set-Setting 'HideLinks' ''
    foreach ($k in $script:optSwitches.Keys) { Set-Setting $k '1' }
    Load-Settings; Apply-Display; Refresh-MapRows
    UI-Log (T '设置：显示内容已恢复默认')
})
$ctl.NavSettings.Add_Click({ $ctl.SetScroll.ScrollToTop() })
# ---------- 清理列表：自己加的文件夹、排除的文件夹 ----------
function Load-CleanLists {
    $c = @(Get-CustomClean); $x = @(Get-ExcludeList)
    $ctl.SetCustomList.ItemsSource = $c; $ctl.SetCustomEmpty.Visibility = if ($c.Count) { 'Collapsed' } else { 'Visible' }
    $ctl.SetExcludeList.ItemsSource = $x; $ctl.SetExcludeEmpty.Visibility = if ($x.Count) { 'Collapsed' } else { 'Visible' }
}
function Save-CleanList([string]$key, [string[]]$items) {
    Set-Setting $key (($items | Where-Object { $_ }) -join '|')
    Load-CleanLists
    # 清理列表变了：扫描结果作废，下次扫描按新的来
    $script:catalog = Get-Catalog
    if ($script:rows -and -not $script:worker) { $ctl.Summary.Text = (T '清理列表改了，请重新扫描。') }
}
function Add-CleanListFolder([bool]$exclude) {
    $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
    $dlg.Description = if ($exclude) { (T '选一个清理时不要碰的文件夹') } else { (T '选一个要清理的文件夹（删里面的东西，文件夹本身保留）') }
    if ($dlg.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
    $p = $dlg.SelectedPath.TrimEnd('\')
    if ($p -match '\|') { Show-Sheet -Kind warn -Title (T '这个路径用不了') -Text (T '路径里不能有竖线。') | Out-Null; return }
    if (-not $exclude) {
        $why = Get-DeleteBlock $p
        if ($why) { Show-Sheet -Kind warn -Title (T '这个文件夹不能加进清理列表') -Text $why | Out-Null; return }
        foreach ($x in (Get-ExcludeList)) { if ($p -ieq $x -or $p.StartsWith("$x\", [StringComparison]::OrdinalIgnoreCase)) { Show-Sheet -Kind warn -Title (T '这个文件夹在排除列表里') -Text ((T "它在排除的 {0} 里面，先把排除去掉。") -f $x) | Out-Null; return } }
    }
    $key = if ($exclude) { 'Exclude' } else { 'CustomClean' }
    $cur = @(if ($exclude) { Get-ExcludeList } else { Get-CustomClean })
    if ($cur -contains $p) { return }
    Save-CleanList $key ($cur + $p)
    OpLog '系统设置' $(if ($exclude) { (T '排除文件夹') } else { (T '加入清理列表') }) $p ''
    UI-Log ((T "{0}：{1}") -f $(if ($exclude) { (T '排除文件夹') } else { (T '加入清理列表') }), $p)
}
$ctl.BtnSetCustomAdd.Add_Click({ Add-CleanListFolder $false })
$ctl.BtnSetExcludeAdd.Add_Click({ Add-CleanListFolder $true })
$removeHandler = [System.Windows.RoutedEventHandler]{
    param($s, $e)
    $b = $e.OriginalSource
    if (-not ($b -is [System.Windows.Controls.Button]) -or $b.Name -ne 'SetListRemove') { return }
    $p = [string]$b.Tag
    $exclude = [object]::ReferenceEquals($s, $ctl.SetExcludeList)
    $key = if ($exclude) { 'Exclude' } else { 'CustomClean' }
    $cur = @(if ($exclude) { Get-ExcludeList } else { Get-CustomClean })
    Save-CleanList $key @($cur | Where-Object { $_ -ne $p })
    OpLog '系统设置' $(if ($exclude) { (T '取消排除') } else { (T '移出清理列表') }) $p ''
}
$ctl.SetCustomList.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, $removeHandler)
$ctl.SetExcludeList.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, $removeHandler)
Load-CleanLists
# 外观、语言：和左下角的按钮共用，换了要重新打开本工具
foreach ($rb in @($ctl.SetThemeLight, $ctl.SetThemeDark, $ctl.SetThemeSystem)) {
    $rb.Add_Checked({
        if ($script:setLoading) { return }
        $to = if ([object]::ReferenceEquals($this, $ctl.SetThemeDark)) { 'dark' } elseif ([object]::ReferenceEquals($this, $ctl.SetThemeSystem)) { 'system' } else { 'light' }
        if (-not (Request-Theme $to)) { Load-Settings }
    })
}
$ctl.SetLangZh.Content = '中文'; $ctl.SetLangEn.Content = 'English'
foreach ($rb in @($ctl.SetLangZh, $ctl.SetLangEn)) {
    $rb.Add_Checked({
        if ($script:setLoading) { return }
        $to = if ([object]::ReferenceEquals($this, $ctl.SetLangEn)) { 'en' } else { 'zh' }
        if ($to -eq $script:Lang -or -not (Request-Lang)) { Load-Settings }
    })
}
Apply-Mode

# ------------------------------------------------------------
# 界面自测（/uitest）：给 GitHub 上的自动测试用，在真的 Windows 上把新加的界面功能点一遍
# ------------------------------------------------------------
function Invoke-UiTest {
    $L = New-Object System.Collections.Generic.List[string]
    $script:uiFail = 0
    $Error.Clear()
    $L.Add(("ClearC UI test {0}  {1:yyyy-MM-dd HH:mm:ss}" -f $script:AppVersion, (Get-Date)))
    # 设置先存一份，测完原样放回去
    $setBak = $null; try { if (Test-Path -LiteralPath $script:settingsFile) { $setBak = [IO.File]::ReadAllBytes($script:settingsFile) } } catch {}
    $fast0 = [bool]$ctl.MapFast.IsChecked
    Set-Setting 'Mode' 'expert'; Apply-Mode
    $step = {
        param([string]$name, [scriptblock]$body)
        $e0 = $Error.Count; $why = $null
        # 检查不通过时 throw 一句说明；代码出了异常也会到这里
        try { $null = & $body } catch { $why = [string]$_.Exception.Message; if ($_.InvocationInfo -and $_.FullyQualifiedErrorId -ne $why) { $why += ' @ ' + ([string]$_.InvocationInfo.PositionMessage).Split([char]10)[0] } }
        # 新增的错误里，找不到文件、外部命令往错误输出写的提示、剪贴板打不开这类（代码里本来就允许的）不算
        $bad = @(); for ($q = 0; $q -lt [math]::Min($Error.Count - $e0, 50); $q++) {
            $x = $Error[$q]; $id = if ($x -is [System.Management.Automation.ErrorRecord]) { [string]$x.FullyQualifiedErrorId + ' ' + [string]$x.CategoryInfo.Category } else { [string]$x.GetType().Name }
            if ($id -notmatch 'NotFound|ObjectNotFound|PathNotFound|ItemNotFound|UnauthorizedAccess|PermissionDenied|NativeCommandError|RemoteException|Clipboard|CLIPBRD|800401D0') { $bad += ([string]$x) + $(if ($x.InvocationInfo) { ' @ ' + ([string]$x.InvocationInfo.PositionMessage).Split([char]10)[0] } else { '' }) }
        }
        if (-not $why -and $bad.Count -gt 0) { $why = 'errors: ' + (($bad | Select-Object -First 3) -join ' | ') }
        if ($why) { $L.Add("FAIL ${name}: $why"); $script:uiFail++ } else { $L.Add("ok   $name") }
    }
    $click = { param($b) $b.RaiseEvent((New-Object System.Windows.RoutedEventArgs ([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent))) }
    $waitUi = {
        param([scriptblock]$cond, [int]$ms)
        $sw = [Diagnostics.Stopwatch]::StartNew()
        do { $f = New-Object System.Windows.Threading.DispatcherFrame; [void]$win.Dispatcher.BeginInvoke([Action]{ $f.Continue = $false }, [System.Windows.Threading.DispatcherPriority]::Background); [System.Windows.Threading.Dispatcher]::PushFrame($f); Start-Sleep -Milliseconds 50 }
        while (-not (& $cond) -and $sw.ElapsedMilliseconds -lt $ms)
        [bool](& $cond)
    }
    # 把一块界面整块画成 PNG，放在报告旁边（GitHub 上的自动测试会一起上传，方便看排版）；画不出来只记一笔，不算失败
    $snap = {
        param($el, [string]$name, [double]$scale = 1)
        try {
            $el.UpdateLayout()
            $w = [math]::Ceiling($el.ActualWidth); $h = [math]::Ceiling($el.ActualHeight)
            if ($w -lt 1 -or $h -lt 1 -or $h -gt 30000) { return }
            $r = New-Object System.Windows.Rect 0, 0, $w, $h
            $vb = New-Object System.Windows.Media.VisualBrush $el
            $vb.ViewboxUnits = [System.Windows.Media.BrushMappingMode]::Absolute; $vb.Viewbox = $r
            $dv = New-Object System.Windows.Media.DrawingVisual
            $dc = $dv.RenderOpen(); $dc.DrawRectangle($win.Background, $null, $r); $dc.DrawRectangle($vb, $null, $r); $dc.Close()
            $bmp = New-Object System.Windows.Media.Imaging.RenderTargetBitmap ([int]($w * $scale)), ([int]($h * $scale)), (96 * $scale), (96 * $scale), ([System.Windows.Media.PixelFormats]::Pbgra32)
            $bmp.Render($dv)
            $enc = New-Object System.Windows.Media.Imaging.PngBitmapEncoder
            $enc.Frames.Add([System.Windows.Media.Imaging.BitmapFrame]::Create($bmp))
            $dir = if ($env:CLEANC_REPORT) { Split-Path ([IO.Path]::GetFullPath($env:CLEANC_REPORT)) } else { $script:appDir }
            $fs = [IO.File]::Create((Join-Path $dir ('uitest-{0}-{1}{2}.png' -f $name, $script:Lang, $(if ([Theme]::Dark) { '-dark' } else { '' }))))
            try { $enc.Save($fs) } finally { $fs.Close() }
        } catch { $L.Add(('note snapshot {0}: {1}' -f $name, $_.Exception.Message)); if ($Error.Count) { $Error.RemoveAt(0) } }
    }
    try {
        & $step 'every page opens' {
            # 「搬家管理」和「软件管理」一打开就在后台开始统计，不在这里点
            foreach ($k in @('clean', 'dup', 'save', 'map', 'auto', 'log', 'help', 'settings')) {
                Show-Page $k; $win.UpdateLayout()
                if ($ctl[$script:pageList[$k][0]].Visibility -ne 'Visible') { throw "page $k not visible" }
            }
        }
        & $step 'help: back to the top after Feedback' {
            Show-Page 'help'; $win.UpdateLayout()
            & $click $ctl.BtnFeedback; $win.UpdateLayout()
            $down = $ctl.HelpScroll.VerticalOffset
            & $click $ctl.NavHelp; $win.UpdateLayout()
            if ($down -le 0) { throw 'Feedback did not scroll down' }
            if ($ctl.HelpScroll.VerticalOffset -ne 0) { throw ("still at {0} after clicking Help" -f $ctl.HelpScroll.VerticalOffset) }
        }
        & $step 'help: sections fold and unfold' {
            Show-Page 'help'; $win.UpdateLayout()
            $all = Get-HelpSections
            if ($all.Count -lt 8) { throw ('only {0} sections' -f $all.Count) }
            if (@($all | Where-Object { $_.IsExpanded }).Count) { throw 'sections should start folded' }
            $h0 = $ctl.HelpScroll.ExtentHeight
            & $snap $ctl.HelpScroll.Content 'help'
            & $click $ctl.BtnHelpExpand; $win.UpdateLayout()
            & $snap $ctl.HelpScroll.Content 'help-open'
            if (@($all | Where-Object { -not $_.IsExpanded }).Count) { throw 'Expand all left some sections folded' }
            if ([string]$ctl.BtnHelpExpand.Content -ne (T '全部收起')) { throw ('button says {0} after expanding' -f $ctl.BtnHelpExpand.Content) }
            if ($ctl.HelpScroll.ExtentHeight -le $h0 + 2000) { throw ('page grew only from {0} to {1}' -f $h0, $ctl.HelpScroll.ExtentHeight) }
            & $click $ctl.BtnHelpExpand; $win.UpdateLayout()
            if (@($all | Where-Object { $_.IsExpanded }).Count) { throw 'Collapse all left some sections open' }
            $q = @($ctl.HelpFaq.Children)[0]
            $q.IsExpanded = $true; $win.UpdateLayout()
            if ([string]$ctl.BtnHelpExpand.Content -ne (T '全部展开')) { throw 'a question changed the sections button' }
            $q.IsExpanded = $false; $ctl.HelpScroll.ScrollToTop(); $win.UpdateLayout()
        }
        & $step 'settings page shows the current settings' {
            Show-Page 'settings'
            if (-not $ctl.SetMapCheck.IsChecked -and (Get-Flag 'MapCheck')) { throw 'item check box switch not loaded' }
            if ([bool]$ctl.SetFast.IsChecked -ne [bool]$ctl.MapFast.IsChecked) { throw 'fast scan switches differ' }
            if ([string]$ctl.SetLangZh.Content -ne '中文' -or [string]$ctl.SetLangEn.Content -ne 'English') { throw 'language names missing' }
        }
        & $step 'display switches hide and show' {
            $pairs = @(@('SetMapCheck', 'MapCkVis'), @('SetMapBar', 'MapBarVis'), @('SetMapPct', 'MapPctVis'), @('SetMapMeta', 'MapMetaVis'), @('SetPageSub', 'SubVis'))
            foreach ($p in $pairs) {
                $ctl[$p[0]].IsChecked = $false; & $click $ctl[$p[0]]
                if ($win.Resources[$p[1]] -ne [System.Windows.Visibility]::Collapsed) { throw "$($p[0]) did not hide $($p[1])" }
                $ctl[$p[0]].IsChecked = $true; & $click $ctl[$p[0]]
                if ($win.Resources[$p[1]] -ne [System.Windows.Visibility]::Visible) { throw "$($p[0]) did not show $($p[1]) again" }
            }
            $ctl.SetMapFastBtn.IsChecked = $false; & $click $ctl.SetMapFastBtn
            if ($ctl.MapFast.Visibility -ne 'Collapsed') { throw 'fast scan switch still shown' }
            $ctl.SetMapFastBtn.IsChecked = $true; & $click $ctl.SetMapFastBtn
            if ($ctl.Hint.Visibility -ne 'Visible') { throw 'page description hidden' }
        }
        & $step 'pages and buttons can be hidden' {
            foreach ($n in 'SetPageMoves', 'SetPageAuto', 'SetPageLog', 'SetLinkLog') { $ctl[$n].IsChecked = $false; & $click $ctl[$n] }
            if ($ctl.NavMoves.Visibility -ne 'Collapsed' -or $ctl.NavLog.Visibility -ne 'Collapsed') { throw 'pages still listed' }
            if ($ctl.NavHeadManage.Visibility -ne 'Collapsed') { throw 'empty group heading still shown' }
            if ($ctl.BtnLog.Visibility -ne 'Collapsed') { throw 'run log button still shown' }
            & $click $ctl.BtnSetReset
            if ($ctl.NavMoves.Visibility -ne 'Visible' -or $ctl.NavHeadManage.Visibility -ne 'Visible' -or $ctl.BtnLog.Visibility -ne 'Visible') { throw 'reset did not show them again' }
            if (-not $ctl.SetPageMoves.IsChecked) { throw 'reset did not update the switches' }
        }
        & $step 'fast scan and low priority switches' {
            Set-FastScan $false; if (-not [DiskMap]::MftOff -or $ctl.SetFast.IsChecked) { throw 'fast scan off not applied' }
            Set-FastScan $true; if ([DiskMap]::MftOff -or -not $ctl.MapFast.IsChecked) { throw 'fast scan on not applied' }
            $ctl.SetLowIo.IsChecked = $true; & $click $ctl.SetLowIo; if (-not [DupFinder]::LowPriority) { throw 'low priority not applied' }
            $ctl.SetLowIo.IsChecked = $false; & $click $ctl.SetLowIo; if ([DupFinder]::LowPriority) { throw 'low priority not cleared' }
        }
        & $step 'appearance change asks first' {
            $n0 = $script:uiSheets.Count
            if (Request-Theme $(if ($script:themePref -eq 'dark') { 'light' } else { 'dark' })) { throw 'theme changed without confirmation' }
            if ($script:uiSheets.Count -le $n0) { throw 'no confirmation asked' }
        }
        & $step 'cleanup list: custom and excluded folders' {
            $d = Join-Path $script:appDir 'uitest-custom'; New-Item -ItemType Directory -Force -Path $d | Out-Null
            [IO.File]::WriteAllBytes((Join-Path $d 'junk.tmp'), (New-Object byte[] 5000))
            Save-CleanList 'CustomClean' @($d)
            if (@($ctl.SetCustomList.ItemsSource).Count -ne 1 -or $ctl.SetCustomEmpty.Visibility -ne 'Collapsed') { throw 'custom list not shown in Settings' }
            $c = @($catalog | Where-Object { $_.Custom })
            if ($c.Count -ne 1 -or (Measure-Item $c[0]) -ne 5000) { throw ("catalog has {0} custom entries" -f $c.Count) }
            Save-CleanList 'Exclude' @($d)
            if ((Measure-Item $c[0]) -ne 0) { throw 'excluded folder still counted' }
            Save-CleanList 'Exclude' @(); Save-CleanList 'CustomClean' @()
            if (@($catalog | Where-Object { $_.Custom }).Count -ne 0 -or $ctl.SetCustomEmpty.Visibility -ne 'Visible') { throw 'custom entry not removed' }
            Remove-Item -LiteralPath $d -Recurse -Force -ErrorAction SilentlyContinue
            & $click $ctl.BtnCleanCustom; $win.UpdateLayout()
            if ($ctl.PageSettings.Visibility -ne 'Visible') { throw 'link did not open Settings' }
        }
        & $step 'reminders: junk limit and cleanup day' {
            Show-Page 'auto'; $win.UpdateLayout()
            $ctl.AutoJunkGB.SelectedIndex = 2; if ((Get-Setting 'JunkGB' '0') -ne '2') { throw 'junk limit not saved' }
            $ctl.AutoCleanWhen.SelectedIndex = 7; if ((Get-Setting 'CleanWhen' '') -ne 'daily') { throw 'cleanup day not saved' }
            $ctl.AutoCleanWhen.SelectedIndex = 0; $ctl.AutoJunkGB.SelectedIndex = 0
        }
        & $step 'apps page: startup, tasks and context menu' {
            $st = @(Get-StartupItems); $tk = @(Get-UserTasks); $cm = @(Get-ContextMenuItems)
            Build-StartRows 'startup' $st; Build-StartRows 'task' $tk; Build-StartRows 'shellex' $cm
            # 列表显示出来（不打开软件页的统计）
            $script:pageLoaded.apps = $true
            Show-Page 'apps'; $ctl.AppsViewStartup.IsChecked = $true; $win.UpdateLayout()
            if ($ctl.StartList.Visibility -ne 'Visible' -or $ctl.AppsList.Visibility -ne 'Collapsed') { throw 'startup view not shown' }
            if (@($ctl.StartList.ItemsSource).Count -ne $st.Count) { throw ("{0} rows for {1} startup items" -f @($ctl.StartList.ItemsSource).Count, $st.Count) }
            $ctl.AppsViewTasks.IsChecked = $true; $win.UpdateLayout()
            if (@($ctl.StartList.ItemsSource).Count -ne $tk.Count) { throw 'task rows differ' }
            $ctl.AppsViewMenu.IsChecked = $true; $win.UpdateLayout()
            if (@($ctl.StartList.ItemsSource).Count -ne $cm.Count) { throw 'context menu rows differ' }
            $ctl.AppsViewApps.IsChecked = $true; $win.UpdateLayout()
            if ($ctl.AppsList.Visibility -ne 'Visible') { throw 'apps view not back' }
            # 开关：在 StartupApproved 里写一个假名字，再删掉，不碰真的启动项
            $ap = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run'
            Set-StartupEnabled $ap 'ClearC-UiTest' $false
            if (Test-StartupEnabled $ap 'ClearC-UiTest') { throw 'disable not recorded' }
            Set-StartupEnabled $ap 'ClearC-UiTest' $true
            if (-not (Test-StartupEnabled $ap 'ClearC-UiTest')) { throw 'enable not recorded' }
            Remove-ItemProperty -LiteralPath $ap -Name 'ClearC-UiTest' -ErrorAction SilentlyContinue
            $script:startRows.Clear()
            "startup {0}, tasks {1}, context menu {2}" -f $st.Count, $tk.Count, $cm.Count
        }
        & $step 'installer orphans are a subset of the cached packages' {
            $all = @(Get-ChildItem -LiteralPath (Join-Path $env:SystemRoot 'Installer') -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Extension -match '^\.(msi|msp)$' })
            $o = @(Get-InstallerOrphans)
            if ($all.Count -gt 0 -and $o.Count -ge $all.Count) { throw ("all {0} packages look orphaned; the references were not read" -f $all.Count) }
            "{0} of {1} packages" -f $o.Count, $all.Count
        }
        & $step 'save space: reserved storage, crash dump, temp folder, OneDrive' {
            Show-Page 'save'; $win.UpdateLayout()
            foreach ($n in 'SaveRsState', 'SaveDumpState', 'SaveTmpState') { if (-not [string]$ctl[$n].Text) { throw "$n is empty" } }
            $dm0 = Get-CrashDumpMode
            if ($dm0 -ge 0) {
                Set-CrashDumpMode 3; if ((Get-CrashDumpMode) -ne 3) { throw 'crash dump mode not written' }
                Set-CrashDumpMode $dm0
            }
            $t0 = Get-UserTemp
            Set-UserTemp "$env:SystemDrive\ClearC-UiTest-Temp"
            if ((Get-UserTemp) -ne "$env:SystemDrive\ClearC-UiTest-Temp") { throw 'temp folder not written' }
            Set-UserTemp $t0
            Remove-Item -LiteralPath "$env:SystemDrive\ClearC-UiTest-Temp" -Recurse -Force -ErrorAction SilentlyContinue
            $od = Get-OneDriveInfo
            if ($null -eq $od -or $null -eq $od.Folders) { throw 'OneDrive info missing' }
            $h = Get-DiskHealth $env:SystemDrive
            if ($h -isnot [string]) { throw 'disk health is not text' }
        }
        & $step 'broken shortcuts and leftover folders are detected' {
            $sh = New-Object -ComObject WScript.Shell
            $lnk = Join-Path $env:APPDATA 'Microsoft\Windows\Start Menu\Programs\ClearC-UiTest.lnk'
            New-Item -ItemType Directory -Force -Path (Split-Path $lnk) | Out-Null
            $s = $sh.CreateShortcut($lnk); $s.TargetPath = "$env:SystemDrive\ClearC-UiTest-Missing\x.exe"; $s.Save()
            try {
                $b = @(Get-BrokenShortcuts)
                if (@($b | Where-Object { $_.FullName -ieq $lnk }).Count -ne 1) { throw ("broken shortcut not found among {0}" -f $b.Count) }
            } finally { Remove-Item -LiteralPath $lnk -Force -ErrorAction SilentlyContinue }
            $d = Join-Path $env:LOCALAPPDATA 'ClearCUiTestOrphan'
            New-Item -ItemType Directory -Force -Path $d | Out-Null
            [IO.File]::WriteAllBytes((Join-Path $d 'old.dat'), (New-Object byte[] 2097152))
            $old = (Get-Date).AddDays(-45)
            (Get-Item -LiteralPath (Join-Path $d 'old.dat')).LastWriteTime = $old; (Get-Item -LiteralPath $d).LastWriteTime = $old
            try {
                $o = @(Get-OrphanFolders @(@{ Name = 'Some App'; Publisher = 'Someone'; Location = 'C:\Program Files\Some App' }))
                if (@($o | Where-Object { $_.Path -ieq $d }).Count -ne 1) { throw ("orphan folder not found among {0}" -f $o.Count) }
                Build-StartRows 'leftover' $o
                $row = @($script:startRows['leftover'] | Where-Object { $_.Detail -ieq $d })[0]
                if (-not $row -or $row.ToggleText -ne (T '移到回收站') -or -not $row.Size) { throw 'leftover row not built' }
                $script:startRows.Clear()
            } finally { Remove-Item -LiteralPath $d -Recurse -Force -ErrorAction SilentlyContinue }
        }
        & $step 'disk health cards fill in' {
            $script:pageLoaded.map = $true; Fill-MapDrives
            Show-Page 'map'; $win.UpdateLayout()
            Start-DiskHealth
            if (-not (& $waitUi { -not $script:dhPs } 60000)) { throw 'disk health did not finish' }
            $cards = @($ctl.MapHealth.ItemsSource)
            if ($cards.Count -eq 0) { throw ('no disk cards; ' + [string]$script:dhErr + ' / direct: ' + (Get-DiskHealth $env:SystemDrive)) }
            if (-not $cards[0].HealthText -or -not $cards[0].UsedText -or $cards[0].Model -eq (T '读不到型号和健康信息')) { throw ('card not filled: ' + $cards[0].Model + ' / ' + $cards[0].HealthText) }
            & $snap $ctl.MapHealthBox 'disk-cards' 2
            $ctl.SetMapHealth.IsChecked = $false; & $click $ctl.SetMapHealth; $win.UpdateLayout()
            $hidden = $ctl.MapHealthBox.Visibility -ne 'Visible'
            $ctl.SetMapHealth.IsChecked = $true; & $click $ctl.SetMapHealth; $win.UpdateLayout()
            if (-not $hidden) { throw 'switch did not hide the disk cards' }
        }
        & $step 'modes hide and show features' {
            Set-Mode 'basic'
            if ($ctl.NavDup.Visibility -ne 'Collapsed' -or $ctl.NavLog.Visibility -ne 'Collapsed' -or $ctl.BtnLog.Visibility -ne 'Collapsed') { throw 'basic mode still shows advanced pages' }
            if ($ctl.SaveCardRs.Visibility -ne 'Collapsed' -or $ctl.AppsViewBox.Visibility -ne 'Collapsed' -or $ctl.MapViewFiles.Visibility -ne 'Collapsed' -or $ctl.BtnSetCustomAdd.Visibility -ne 'Collapsed') { throw 'basic mode still shows advanced cards' }
            if ($ctl.NavClean.Visibility -ne 'Visible' -or $ctl.SaveCardCos.Visibility -ne 'Visible' -or $ctl.SaveCardOd.Visibility -ne 'Visible' -or $ctl.NavHealth.Visibility -ne 'Visible' -or $ctl.HealthCardHw.Visibility -ne 'Visible') { throw 'basic mode hides basic things' }
            if ($ctl.HealthCardBoot.Visibility -ne 'Collapsed' -or $ctl.HealthCardMon.Visibility -ne 'Collapsed') { throw 'basic mode shows advanced health cards' }
            if ($ctl.ModeTag.Text -ne ((T '普通用户') + (T '模式'))) { throw ('mode tag: ' + $ctl.ModeTag.Text) }
            Set-Mode 'pro'
            if ($ctl.NavDup.Visibility -ne 'Visible' -or $ctl.AppsViewStartup.Visibility -ne 'Visible' -or $ctl.AppsViewTasks.Visibility -ne 'Collapsed' -or $ctl.SaveCardPf.Visibility -ne 'Visible' -or $ctl.SaveCardRs.Visibility -ne 'Collapsed') { throw 'pro mode wrong' }
            Set-Mode 'expert'
            if ($ctl.AppsViewTasks.Visibility -ne 'Visible' -or $ctl.SaveCardRs.Visibility -ne 'Visible' -or $ctl.BtnLog.Visibility -ne 'Visible' -or $ctl.BtnSetCustomAdd.Visibility -ne 'Visible' -or $ctl.BtnSfcRepair.Visibility -ne 'Visible' -or $ctl.HealthCardEvents.Visibility -ne 'Visible') { throw 'expert mode wrong' }
            if (@($catalog | Where-Object { [int]$_.Lvl -eq 2 }).Count -lt 5 -or @($catalog | Where-Object { [int]$_.Lvl -eq 1 }).Count -lt 5) { throw 'catalog levels missing' }
        }
        & $step 'cleanup tiers: careful group, delete preview, recycle switch' {
            $care = @($catalog | Where-Object { $_.Careful })
            if ($care.Count -lt 10 -or @($care | Where-Object { -not ([string]$_.G).StartsWith('谨慎清理') }).Count -gt 0) { throw ("careful items: {0}" -f $care.Count) }
            if (@($catalog | Where-Object { $_.N -eq (T '驱动存储里的旧版驱动包') }).Count -ne 1) { throw 'old driver packages item missing' }
            $d = Join-Path $script:appDir 'uitest-preview'; New-Item -ItemType Directory -Path "$d\sub" -Force | Out-Null
            [IO.File]::WriteAllText("$d\a.tmp", ('x' * 3000)); [IO.File]::WriteAllText("$d\sub\b.tmp", ('y' * 5000)); [IO.File]::WriteAllText("$d\keep.txt", 'z')
            try {
                $pv = @(Get-DeletePreview @(@{ N = 'test'; Paths = @($d); Filter = '*.tmp' }) 100)
                if ($pv.Count -ne 1 -or $pv[0].Bytes -ne 3000) { throw ("preview with filter: {0}" -f $pv.Count) }
                $pv = @(Get-DeletePreview @(@{ N = 'test'; Paths = @($d) }) 100)
                if ($pv.Count -ne 3 -or @($pv | Where-Object { $_.IsDir }).Count -ne 1) { throw ("preview: {0}" -f $pv.Count) }
                $n0 = $script:uiSheets.Count
                Show-DeletePreview @(@{ N = 'test'; Paths = @($d) })
                if ($script:uiSheets.Count -le $n0 -or $script:uiSheets[$script:uiSheets.Count - 1] -notmatch 'preview-') { throw 'preview dialog not shown' }
            } finally { Remove-Item -LiteralPath $d -Recurse -Force -ErrorAction SilentlyContinue }
            Show-Page 'settings'; $ctl.SetRecycle.IsChecked = $true; & $click $ctl.SetRecycle
            if ((Get-Setting 'Recycle' '0') -ne '1') { throw 'recycle setting not saved' }
            $ctl.SetRecycle.IsChecked = $false; & $click $ctl.SetRecycle
        }
        & $step 'system health page fills in' {
            Show-Page 'health'
            if (-not (& $waitUi { $script:healthData -ne $null } 90000)) { throw ('health data not read: ' + $ctl.HealthNote.Text) }
            $L.Add(('health: ' + $ctl.HealthNote.Text))
            if ($ctl.HealthCards.Items.Count -lt 3) { throw ("only {0} hardware cards" -f $ctl.HealthCards.Items.Count) }
            $titles = @($ctl.HealthCards.Items | ForEach-Object { $_.Title })
            if ($titles -notcontains (T 'CPU') -or $titles -notcontains (T '内存') -or $titles -notcontains 'Windows') { throw ('cards: ' + ($titles -join ',')) }
            foreach ($c in $ctl.HealthCards.Items) { $L.Add(('  ' + $c.Title + ': ' + (@($c.Chips | ForEach-Object { $_.Text }) -join ' | ') + ' / ' + (@($c.Lines) -join ' / '))) }
            if (-not $ctl.HealthBootText.Text -or -not $ctl.HealthCrashText.Text -or -not $ctl.HealthWinText.Text) { throw 'boot, crash or events text empty' }
            $L.Add(('  boot: ' + $ctl.HealthBootText.Text)); $L.Add(('  crash: ' + $ctl.HealthCrashText.Text)); $L.Add(('  events: ' + $ctl.HealthWinText.Text))
            # 活动监控：采两次样
            Start-Monitor
            if (-not (& $waitUi { $script:monShared -and $script:monShared.Ver -ge 1 } 20000)) { throw 'monitor took no sample' }
            Refresh-Monitor
            if ($ctl.MonList.Items.Count -lt 1) { throw 'monitor list empty' }
            $L.Add(('  monitor: ' + $ctl.MonList.Items.Count + ' rows, top ' + $ctl.MonList.Items[0].Name + ' ' + $ctl.MonList.Items[0].SinceText))
            $ctl.MonSortCpu.IsChecked = $true; if ($ctl.MonList.Items.Count -lt 1) { throw 'monitor list empty after sort' }
            Stop-Monitor
            if ($ctl.BtnMonStop.IsEnabled -or -not $script:monShared.Stop) { throw 'monitor not stopped' }
            if (-not (& $waitUi { -not $script:bg['monitor'] } 15000)) { throw 'monitor thread did not end' }
            # 系统文件检查按钮只是起终端：不点，查它在不在
            if ($ctl.BtnSfcCheck.Visibility -ne 'Visible') { throw 'sfc check button hidden' }
        }
        & $step 'similar photos and keep rules' {
            if (-not ('PhotoHash' -as [type])) { throw 'PhotoHash did not compile' }
            $d = Join-Path $script:appDir 'uitest-photos'; New-Item -ItemType Directory -Path "$d\sub" -Force | Out-Null
            # 画三张图：渐变图、它的缩小版（相似）、另一张方格图（不相似）
            $draw = { param([string]$file, [int]$w, [int]$h, [bool]$checker)
                $dv = New-Object System.Windows.Media.DrawingVisual
                $dc = $dv.RenderOpen()
                if ($checker) { for ($x = 0; $x -lt 8; $x++) { for ($y = 0; $y -lt 8; $y++) { $c = if (($x + $y) % 2 -eq 0) { [System.Windows.Media.Brushes]::Black } else { [System.Windows.Media.Brushes]::White }; $dc.DrawRectangle($c, $null, (New-Object System.Windows.Rect ($x * $w / 8), ($y * $h / 8), ($w / 8), ($h / 8))) } } }
                else { $br = New-Object System.Windows.Media.LinearGradientBrush ([System.Windows.Media.Colors]::Black), ([System.Windows.Media.Colors]::White), 0; $dc.DrawRectangle($br, $null, (New-Object System.Windows.Rect 0, 0, $w, $h)); $dc.DrawEllipse([System.Windows.Media.Brushes]::Red, $null, (New-Object System.Windows.Point ($w * 0.3), ($h * 0.6)), ($w * 0.15), ($h * 0.15)) }
                $dc.Close()
                $rt = New-Object System.Windows.Media.Imaging.RenderTargetBitmap $w, $h, 96, 96, ([System.Windows.Media.PixelFormats]::Pbgra32); $rt.Render($dv)
                $enc = New-Object System.Windows.Media.Imaging.PngBitmapEncoder; $enc.Frames.Add([System.Windows.Media.Imaging.BitmapFrame]::Create($rt))
                $fs = [IO.File]::Create($file); try { $enc.Save($fs) } finally { $fs.Dispose() }
            }
            & $draw "$d\a.png" 640 480 $false; & $draw "$d\sub\a-small.png" 160 120 $false; & $draw "$d\other.png" 640 480 $true
            try {
                $w1 = 0; $h1 = 0; $ha = [PhotoHash]::Hash("$d\a.png", [ref]$w1, [ref]$h1); $hb = [PhotoHash]::Hash("$d\sub\a-small.png", [ref]$w1, [ref]$h1); $hc = [PhotoHash]::Hash("$d\other.png", [ref]$w1, [ref]$h1)
                $dab = [PhotoHash]::Dist($ha, $hb); $dac = [PhotoHash]::Dist($ha, $hc)
                $L.Add(("photo hash: a~small {0} bits, a~other {1} bits" -f $dab, $dac))
                if ($dab -gt 6 -or $dac -lt 12) { throw ("hash distances a~small {0}, a~other {1}" -f $dab, $dac) }
                $list = [PhotoHash]::Scan([string[]]@($d), 1, 0, 1000); [PhotoHash]::HashAll($list)
                if ($list.Count -ne 3) { throw ("scan found {0} photos" -f $list.Count) }
                $ng = [PhotoHash]::Group($list, 8)
                $byG = @{}; foreach ($p in $list) { $byG[$p.Group] = [int]$byG[$p.Group] + 1 }
                if (@($byG.Values | Where-Object { $_ -eq 2 }).Count -ne 1 -or $ng -ne 2) { throw ("groups: {0}" -f (($list | ForEach-Object { $_.Path + '=' + $_.Group }) -join ', ')) }
                # 走一遍真正的查找（后台线程）
                Show-Page 'dup'; $ctl.ModeSimilar.IsChecked = $true
                if ($ctl.SimilarRow.Visibility -ne 'Visible') { throw 'similarity row hidden' }
                Start-SimilarScan @($d) @{ Ok = $true; Min = 1; Max = 0 }
                if (-not (& $waitUi { -not $script:worker } 60000)) { throw 'similar scan did not finish' }
                if (-not $script:dupRows -or $script:dupRows.Count -ne 2 -or -not $script:dupSimilar) { throw ("similar rows: {0}" -f $(if ($script:dupRows) { $script:dupRows.Count } else { 0 })) }
                if (@($script:dupRows | Where-Object { $_.ToDelete }).Count -ne 0) { throw 'similar photos were auto-checked' }
                if ($script:dupRows[0].Path -ne "$d\a.png" -or -not $script:dupRows[0].HasRisk) { throw 'largest photo not first, or no note' }
                # 留法：路径最短的、某个文件夹里的
                Pick-Dup 'short'
                if (-not $script:dupRows[1].ToDelete -or $script:dupRows[0].ToDelete) { throw 'keep shortest path wrong' }
                $script:keepInDir = "$d\sub\"; Pick-Dup 'in'
                if (-not $script:dupRows[0].ToDelete -or $script:dupRows[1].ToDelete) { throw 'keep in folder wrong' }
                $script:keepInDir = ''
                # 相似照片：不能合并，永久删除会被改成回收站
                $n0 = $script:uiSheets.Count; & $click $ctl.BtnDupMerge
                if ($script:uiSheets.Count -le $n0) { throw 'merge of similar photos not refused' }
                $ctl.DupRecycle.IsChecked = $false; $n0 = $script:uiSheets.Count; & $click $ctl.BtnDupDelete
                if (-not $ctl.DupRecycle.IsChecked -or $script:uiSheets.Count -lt $n0 + 2) { throw 'delete of similar photos did not force the recycle bin' }
                if ($script:worker) { throw 'delete started although the dialog was cancelled' }
                $ctl.DupRecycle.IsChecked = $true
            } finally { $ctl.ModeName.IsChecked = $true; $script:dupRows = $null; $script:dupByGroup = @{}; $script:dupSimilar = $false; $ctl.DupList.ItemsSource = $null; Remove-Item -LiteralPath $d -Recurse -Force -ErrorAction SilentlyContinue }
        }
        & $step 'restore points card' {
            Show-Page 'save'
            $sw = [Diagnostics.Stopwatch]::StartNew()
            # 在另一个线程里读：等它读完（界面照常响应）
            while ($script:rpPs -and $sw.ElapsedMilliseconds -lt 30000) { $f = New-Object System.Windows.Threading.DispatcherFrame; [void]$win.Dispatcher.BeginInvoke([Action]{ $f.Continue = $false }, [System.Windows.Threading.DispatcherPriority]::Background); [System.Windows.Threading.Dispatcher]::PushFrame($f); Start-Sleep -Milliseconds 50 }
            $t = [string]$ctl.SaveRpState.Text
            if (-not $t -or $t -eq (T '当前：正在读取…')) { throw ("not filled in: {0}" -f $t) }
        }
        # 空间地图：用一个小文件夹扫出来的树
        $tree = [DiskMap]::Scan("$env:SystemRoot\INF", 2)      # 每台 Windows 都有，文件和子文件夹都不少
        & $step 'space map rows' {
            [DiskMap]::Use($tree); $script:mapRoot = $tree; $script:mapCur = $tree; $script:mapScanAt = Get-Date; $script:mapHow = 'test'
            Show-Page 'map'; $ctl.MapViewDirs.IsChecked = $true; Show-MapLevel $tree; $win.UpdateLayout()
            if ($ctl.MapList.Items.Count -lt 2) { throw ("only {0} rows" -f $ctl.MapList.Items.Count) }
            if ($ctl.BtnMapAcct.Visibility -ne 'Collapsed') { throw 'space breakdown shown for a folder scan' }
        }
        & $step 'item check boxes select rows' {
            $lv = $ctl.MapList; $lv.UnselectAll(); $win.UpdateLayout()
            $c0 = $lv.ItemContainerGenerator.ContainerFromIndex(0); $c1 = $lv.ItemContainerGenerator.ContainerFromIndex(1)
            if (-not $c0 -or -not $c1) { throw 'rows not generated' }
            $k0 = Find-Visual $c0 ([System.Windows.Controls.CheckBox]); $k1 = Find-Visual $c1 ([System.Windows.Controls.CheckBox])
            if (-not $k0) { throw 'no check box in the row' }
            if (-not $k0.IsVisible) { throw 'check box not visible' }
            $k0.IsChecked = $true; $k1.IsChecked = $true
            if ($lv.SelectedItems.Count -ne 2) { throw ("{0} selected after ticking 2" -f $lv.SelectedItems.Count) }
            if ($null -ne $ctl.MapAll.IsChecked) { throw 'select all is not partly checked' }
            $k0.IsChecked = $false
            if ($lv.SelectedItems.Count -ne 1) { throw 'unticking did not unselect' }
            $lv.SelectedItem = $lv.Items[0]; $win.UpdateLayout()
            if (-not $k0.IsChecked -or $k1.IsChecked) { throw 'check boxes do not follow the selection' }
            $ctl.SetMapCheck.IsChecked = $false; & $click $ctl.SetMapCheck; $win.UpdateLayout()
            $hidden = -not $k0.IsVisible
            $ctl.SetMapCheck.IsChecked = $true; & $click $ctl.SetMapCheck; $win.UpdateLayout()
            if (-not $hidden) { throw 'switch did not hide the check boxes' }
        }
        & $step 'with check boxes only the box selects' {
            $lv = $ctl.MapList; $lv.UnselectAll(); $win.UpdateLayout()
            if ($lv.Items.Count -lt 8) { throw 'too few rows' }
            if (-not (Test-CheckMode)) { throw 'check box mode is off' }
            $p = Invoke-RowPress 3 'Left' $false $false
            if (-not $p.Handled -or $lv.SelectedItems.Count -ne 0) { throw 'a click on a row (not the box) would select it' }
            foreach ($q in 0, 2) {
                $k = Find-Visual ($lv.ItemContainerGenerator.ContainerFromIndex($q)) ([System.Windows.Controls.CheckBox])
                $k.IsChecked = $true; $k.RaiseEvent((New-Object System.Windows.RoutedEventArgs ([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent)))
            }
            $p = Invoke-RowPress 4 'Left' $false $false
            if (-not $p.Handled -or $lv.SelectedItems.Count -ne 2) { throw ("clicking a row after ticking: {0} selected, expected the 2 ticked" -f $lv.SelectedItems.Count) }
            $p = Invoke-RowPress 5 'Right' $false $false
            if (-not $p.Handled -or $lv.SelectedItems.Count -ne 2) { throw 'a right click selected the row' }
            $script:menuRow = $lv.Items[5]
            if (-not (Update-MapMenu) -or @($script:menuRows).Count -ne 1 -or -not [object]::ReferenceEquals(@($script:menuRows)[0], $lv.Items[5])) { throw 'the menu is not for the right-clicked row only' }
            $script:menuRow = $lv.Items[2]; [void](Update-MapMenu)
            if (@($script:menuRows).Count -ne 2) { throw 'the menu on a ticked row is not for all ticked rows' }
            $script:menuRow = $null
            $p = Invoke-RowPress 6 'Left' $true $false
            if ($lv.SelectedItems.Count -ne 6) { throw ("shift-click: {0} selected, expected 6" -f $lv.SelectedItems.Count) }
            $p = Invoke-RowPress 7 'Left' $false $false
            if (-not $p.Add -or $p.NoDrag) { throw 'dragging from a row would not add to the ticks' }
            Refresh-MapRows; $win.UpdateLayout()
            if ($lv.SelectedItems.Count -ne 6) { throw ("refreshing the list kept {0} of 6" -f $lv.SelectedItems.Count) }
            $src = [System.Windows.PresentationSource]::FromVisual($lv)
            if ($src) {
                $ka = New-Object System.Windows.Input.KeyEventArgs ([System.Windows.Input.Keyboard]::PrimaryDevice), $src, 0, ([System.Windows.Input.Key]::Escape)
                $ka.RoutedEvent = [System.Windows.Input.Keyboard]::PreviewKeyDownEvent
                $lv.RaiseEvent($ka)
                if ($lv.SelectedItems.Count -ne 0) { throw 'Esc did not clear the ticks' }
            }
        }
        & $step 'real mouse: click, double-click, check box' {
            # 用真的鼠标点（SetCursorPos + mouse_event）。窗口先挪到屏幕上、放在最前面；这台机器收不到模拟的鼠标就跳过
            if (-not ('UiInput' -as [type])) { Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; public static class UiInput { [DllImport("user32.dll")] public static extern bool SetCursorPos(int x, int y); [DllImport("user32.dll")] public static extern void mouse_event(uint f, uint dx, uint dy, uint d, UIntPtr e); }' }
            $pump = { param([int]$ms) $sw = [Diagnostics.Stopwatch]::StartNew(); while ($sw.ElapsedMilliseconds -lt $ms) { $f = New-Object System.Windows.Threading.DispatcherFrame; [void]$win.Dispatcher.BeginInvoke([Action]{ $f.Continue = $false }, [System.Windows.Threading.DispatcherPriority]::Background); [System.Windows.Threading.Dispatcher]::PushFrame($f); Start-Sleep -Milliseconds 15 } }
            $at = { param($el, [int]$times)
                $pt = $el.PointToScreen((New-Object System.Windows.Point ([double]$el.ActualWidth / 2), ([double]$el.ActualHeight / 2)))
                [void][UiInput]::SetCursorPos([int]$pt.X, [int]$pt.Y); Start-Sleep -Milliseconds 80; & $pump 120
                for ($q = 0; $q -lt $times; $q++) { [UiInput]::mouse_event(2, 0, 0, 0, [UIntPtr]::Zero); Start-Sleep -Milliseconds 25; [UiInput]::mouse_event(4, 0, 0, 0, [UIntPtr]::Zero); Start-Sleep -Milliseconds 40 }
                & $pump 500
            }
            $lv = $ctl.MapList
            $x0 = $win.Left; $y0 = $win.Top
            try {
                $win.Left = 0; $win.Top = 0; $win.Topmost = $true; $win.Activate() | Out-Null; & $pump 400
                Show-MapLevel $tree; $lv.UnselectAll(); $win.UpdateLayout(); & $pump 200
                $k0 = Find-Visual ($lv.ItemContainerGenerator.ContainerFromIndex(0)) ([System.Windows.Controls.CheckBox])
                & $at $k0 1
                if ($lv.SelectedItems.Count -ne 1) { $L.Add('       (real mouse input does not reach the window on this machine; skipped)'); return }
                if (-not $k0.IsMouseOver) { throw 'the pointer on the check box is not seen as over it' }
                $t1 = Find-Visual ($lv.ItemContainerGenerator.ContainerFromIndex(1)) ([System.Windows.Controls.TextBlock])
                & $at $t1 1
                if ($lv.SelectedItems.Count -ne 1) { throw ("a click on a row's name changed the selection to {0}" -f $lv.SelectedItems.Count) }
                & $at $k0 2
                if ($lv.SelectedItems.Count -ne 1 -or -not [object]::ReferenceEquals($script:mapCur, $tree)) { throw 'a double click on the check box did something else than tick twice' }
                $di = -1; for ($q = 0; $q -lt $lv.Items.Count; $q++) { $r = $lv.Items[$q]; if ($r.IsDir -and $r.Node) { $di = $q; break } }
                if ($di -lt 0) { throw 'no folder row to double-click' }
                $lv.ScrollIntoView($lv.Items[$di]); $win.UpdateLayout(); & $pump 200
                $want = $lv.Items[$di].Node
                $td = Find-Visual ($lv.ItemContainerGenerator.ContainerFromIndex($di)) ([System.Windows.Controls.TextBlock])
                & $at $td 2
                if (-not [object]::ReferenceEquals($script:mapCur, $want)) { throw ("double-click did not open the folder (now at {0})" -f $script:mapCur.FullPath()) }
                # 关掉复选框再试一次：单击选中，双击照样进
                Show-MapLevel $tree; $win.Resources['MapCkVis'] = [System.Windows.Visibility]::Collapsed; $lv.UnselectAll(); $win.UpdateLayout(); & $pump 200
                $t1 = Find-Visual ($lv.ItemContainerGenerator.ContainerFromIndex(1)) ([System.Windows.Controls.TextBlock])
                & $at $t1 1
                if ($lv.SelectedItems.Count -ne 1) { throw 'without check boxes a click does not select the row' }
                $lv.ScrollIntoView($lv.Items[$di]); $win.UpdateLayout(); & $pump 200
                $td = Find-Visual ($lv.ItemContainerGenerator.ContainerFromIndex($di)) ([System.Windows.Controls.TextBlock])
                & $at $td 2
                if (-not [object]::ReferenceEquals($script:mapCur, $want)) { throw 'without check boxes double-click did not open the folder' }
            } finally {
                $win.Resources['MapCkVis'] = [System.Windows.Visibility]::Visible
                $win.Topmost = $false; $win.Left = $x0; $win.Top = $y0
                Show-MapLevel $tree; $lv.UnselectAll(); $win.UpdateLayout()
            }
        }
        & $step 'select all' {
            $lv = $ctl.MapList
            & $click $ctl.MapAll; if ($lv.SelectedItems.Count -ne $lv.Items.Count -or $ctl.MapAll.IsChecked -ne $true) { throw 'not all selected' }
            & $click $ctl.MapAll; if ($lv.SelectedItems.Count -ne 0 -or $ctl.MapAll.IsChecked -ne $false) { throw 'not all cleared' }
        }
        & $step 'left and right drag select a run of rows' {
            $lv = $ctl.MapList; $n = $lv.Items.Count; $win.UpdateLayout()   # 列表刚换过内容：先排好版，行才生成出来
            if ($n -lt 3) { throw 'too few rows' }
            if ((Get-RowAt $lv 6) -ne 0) { throw ("row at the top is {0}" -f (Get-RowAt $lv 6)) }
            $lv.UnselectAll()
            foreach ($btn in 'Right', 'Left') {
                $lv.UnselectAll()
                $d = @{ Lv = $lv; Anchor = 0; Cur = 0; Moved = $false; Ctrl = $false; Base = $null; Cap = $null; Button = $btn }; $script:rdrag = $d
                Start-RowDrag $d; Set-DragRange $d 2
                if ($lv.SelectedItems.Count -ne 3) { throw ("{0}: {1} selected for rows 0-2" -f $btn, $lv.SelectedItems.Count) }
                Set-DragRange $d 1
                if ($lv.SelectedItems.Count -ne 2) { throw "${btn}: dragging back did not shrink the selection" }
                Stop-RowDrag
                if ($script:rdrag) { throw "${btn}: drag not stopped" }
                $lv.UnselectAll(); [void]$lv.SelectedItems.Add($lv.Items[$n - 1])
                $d = @{ Lv = $lv; Anchor = 0; Cur = 0; Moved = $false; Ctrl = $true; Base = $null; Cap = $null; Button = $btn }; $script:rdrag = $d
                Start-RowDrag $d; Set-DragRange $d 1; Stop-RowDrag
                if ($lv.SelectedItems.Count -ne 3) { throw ("{0} with Ctrl: {1} selected, expected 3" -f $btn, $lv.SelectedItems.Count) }
            }
            $c0 = $lv.ItemContainerGenerator.ContainerFromIndex(0); $k0 = Find-Visual $c0 ([System.Windows.Controls.CheckBox]); $t0 = Find-Visual $c0 ([System.Windows.Controls.TextBlock])
            if (-not (Test-InCheckBox $lv (Find-Visual $k0 ([System.Windows.Controls.Border])))) { throw 'a press on the check box would start a drag' }
            if ($t0 -and (Test-InCheckBox $lv $t0)) { throw 'a press on the name is taken for the check box' }
        }
        & $step 'right-click menu' {
            $lv = $ctl.MapList; $lv.UnselectAll(); $script:menuRow = $null
            if (Update-MapMenu) { throw 'menu would open with nothing selected' }
            $lv.SelectAll()
            if (-not (Update-MapMenu)) { throw 'menu would not open' }
            $lv.ContextMenu.PlacementTarget = $lv; $lv.ContextMenu.IsOpen = $true; $win.UpdateLayout(); $lv.ContextMenu.IsOpen = $false
            $lv.UnselectAll(); $lv.SelectedItem = $lv.Items[0]; [void](Update-MapMenu)
            if ($ctl.MmEnter.Visibility -ne 'Visible' -and $lv.Items[0].IsDir) { throw 'Open folder missing for a folder' }
            $want = [string]$lv.Items[0].Path
            $ctl.MmCopy.RaiseEvent((New-Object System.Windows.RoutedEventArgs ([System.Windows.Controls.MenuItem]::ClickEvent)))
            # 剪贴板偶尔被别的程序占着打不开：读不到就不算这一项
            $got = ''; try { $got = [string][System.Windows.Clipboard]::GetText() } catch {}
            if ($got -and $got -ne $want) { throw ("copy path: clipboard has {0}, expected {1}" -f $got, $want) }
        }
        & $step 'size on disk notes' {
            $t = Get-DiskNote 2GB 200MB 1GB $false
            if ($t -notmatch [regex]::Escape((Fmt 1GB)) -or $t -notmatch [regex]::Escape((Fmt 200MB))) { throw "note: $t" }
            if (Get-DiskNote 100MB 100MB 0 $false) { throw 'note for an ordinary folder' }
            $tree.HasDisk = $true; $tree.UniqueSize = $tree.Size; $tree.UniqueDisk = $tree.Size; $tree.MftBytes = 64MB
            Show-MapLevel $tree
            if ($ctl.BtnMapAcct.Visibility -ne 'Visible') { throw 'space breakdown link hidden' }
            $n0 = $script:uiSheets.Count; & $click $ctl.BtnMapAcct
            if ($script:uiSheets.Count -le $n0 -or $script:uiSheets[$script:uiSheets.Count - 1] -notmatch 'MFT') { throw 'space breakdown not shown' }
        }
        & $step 'other map views' {
            $ctl.MapViewTree.IsChecked = $true; $win.UpdateLayout()
            $ctl.MapViewFiles.IsChecked = $true; $win.UpdateLayout()
            $ctl.MapViewGrow.IsChecked = $true; $win.UpdateLayout()
            if ($ctl.MapAll.IsEnabled) { throw 'select all enabled in the comparison view' }
            $ctl.MapViewTree.IsChecked = $true
            if ($ctl.MapAll.IsEnabled) { throw 'select all enabled in the treemap' }
            $ctl.MapViewDirs.IsChecked = $true
        }
        & $step 'file types view' {
            $ctl.MapViewTypes.IsChecked = $true; $win.UpdateLayout()
            if ($ctl.MapList.Items.Count -lt 1) { throw 'no type rows' }
            $sum = [long]0; foreach ($r in $ctl.MapList.Items) { $sum += $r.FileCount }
            if ($sum -ne $tree.Files) { throw ("type counts {0} != files {1}" -f $sum, $tree.Files) }
            $first = $ctl.MapList.Items[0]
            if (-not (Enter-MapRow $first)) { throw 'type row does not open the file search' }
            if (-not $ctl.MapViewFiles.IsChecked -or [string]$ctl.MapType.SelectedItem.Tag -ne ([string]$first.Path).Substring(5)) { throw 'file search not set to that type' }
            if ($ctl.MapOwner.Items.Count -lt 2 -and $ctl.MapList.Items.Count -gt 0) { throw 'no owners listed' }
            $ctl.MapSort.SelectedIndex = 1; $win.UpdateLayout()
            if ($ctl.MapList.Items.Count -gt 1 -and [string]$ctl.MapList.Items[0].When -lt [string]$ctl.MapList.Items[1].When) { throw 'not sorted by date' }
            $ctl.MapSort.SelectedIndex = 0; $ctl.MapType.SelectedIndex = 0
        }
        & $step 'treemap and list are linked' {
            $ctl.MapViewDirs.IsChecked = $true; Show-MapLevel $tree
            $ctl.MapViewTree.IsChecked = $true; $win.UpdateLayout(); [void](& $waitUi { $ctl.MapTree.Children.Count -gt 0 } 3000)
            if ($ctl.MapList.Visibility -ne 'Visible' -or $ctl.MapTree.Children.Count -lt 1) { throw 'treemap without the list' }
            $row = $ctl.MapList.Items[0]
            $ctl.MapList.SelectedItems.Clear(); $ctl.MapList.SelectedItem = $row; $win.UpdateLayout()
            $blk = $null; foreach ($b in $ctl.MapTree.Children) { if ([object]::ReferenceEquals($b.Tag, $row)) { $blk = $b } }
            if (-not $blk) { throw 'no block for the first row' }
            if ($blk.BorderBrush.Color.A -eq 0) { throw 'selected row not outlined on the treemap' }
            # 点第二块：列表里选中的换成它
            $blk2 = $null; foreach ($b in $ctl.MapTree.Children) { if ($b.Tag -and -not [object]::ReferenceEquals($b.Tag, $row)) { $blk2 = $b; break } }
            if ($blk2) {
                $ev = New-Object System.Windows.Input.MouseButtonEventArgs ([System.Windows.Input.Mouse]::PrimaryDevice), 0, ([System.Windows.Input.MouseButton]::Left)
                $ev.RoutedEvent = [System.Windows.UIElement]::MouseLeftButtonDownEvent
                $blk2.RaiseEvent($ev); $win.UpdateLayout()
                if (-not [object]::ReferenceEquals($ctl.MapList.SelectedItem, $blk2.Tag)) { throw 'clicking a block did not select the row' }
                if ($blk.BorderBrush.Color.A -ne 0 -or $blk2.BorderBrush.Color.A -eq 0) { throw 'outline did not move to the clicked block' }
            }
            $ctl.MapViewDirs.IsChecked = $true
        }
        if ($env:CLEANC_SHOTS -eq '1') {
            & $step 'screenshots for the README' {
                $root = $win.Content
                $win.Width = 1240; $win.Height = 860
                $shot = { param([string]$n) $win.UpdateLayout(); [void](& $waitUi { $false } 300); & $snap $root ('shot-' + $n) 2 }
                # 清理 C 盘：真的扫一遍（只统计大小，不删东西）
                Show-Page 'clean'; & $click $ctl.BtnScan
                if (-not (& $waitUi { -not $script:worker } 150000)) { throw 'cleanup scan did not finish' }
                if (-not $script:rows) { throw 'cleanup scan found nothing' }
                $ctl.OpPanel.Visibility = 'Collapsed'; & $shot 'clean'
                # 空间地图：扫整个 C 盘
                Show-Page 'map'; $ctl.MapViewDirs.IsChecked = $true
                foreach ($it in $ctl.MapDrive.Items) { if ([string]$it.Tag -ieq "$env:SystemDrive\") { $ctl.MapDrive.SelectedItem = $it } }
                Start-MapScan "$env:SystemDrive\"
                if (-not (& $waitUi { -not $script:worker } 120000)) { throw 'space map scan did not finish' }
                if (-not $script:mapRoot -or [object]::ReferenceEquals($script:mapRoot, $tree)) { throw 'space map has no scan of the drive' }
                $ctl.OpPanel.Visibility = 'Collapsed'; & $shot 'map'
                if ($ctl.MapOverview.Visibility -ne 'Visible' -or -not $ctl.MapOvPct.Text) { throw 'drive overview missing' }
                $ctl.MapViewTree.IsChecked = $true; & $shot 'map-tree'
                $ctl.MapViewTypes.IsChecked = $true; & $shot 'map-types'
                if ($ctl.MapList.Items.Count -lt 3) { throw 'type statistics missing for the drive' }
                # 最近改动：读变更日志（要文件表在内存里）
                $ctl.MapViewRecent.IsChecked = $true; Start-MapRecent
                if (-not (& $waitUi { -not $script:worker } 90000)) { throw 'recent changes did not finish' }
                $L.Add(("recent changes: {0} folders; {1}" -f @($script:recentRows).Count, $script:recentNote))
                if ([string]$script:mapMethod -like 'mft*' -and @($script:recentRows).Count -lt 1 -and $script:recentNote -notmatch 'USN') { throw ('no recent changes: ' + $script:recentNote) }
                & $shot 'map-recent'
                # 再扫一次：和上次比要能说出增长在哪
                Start-MapScan "$env:SystemDrive\"
                if (-not (& $waitUi { -not $script:worker } 120000)) { throw 'second space map scan did not finish' }
                $ctl.OpPanel.Visibility = 'Collapsed'
                $ctl.MapViewGrow.IsChecked = $true; $win.UpdateLayout()
                $L.Add('growth: ' + $script:growSummary)
                if (-not $script:growSummary) { throw 'no growth summary after the second scan' }
                $ctl.MapGrowBase.SelectedIndex = 5; $win.UpdateLayout()
                if ($script:growNote -notmatch '\d{8}-\d{4}') { throw ('baseline note: ' + $script:growNote) }
                $ctl.MapGrowBase.SelectedIndex = 0
                $ctl.MapViewDirs.IsChecked = $true
                Show-Page 'save'; $ctl.SaveScroll.ScrollToTop(); & $shot 'save'
                Show-Page 'dup'; & $shot 'dup'
                Show-Page 'settings'; & $shot 'settings'
                # 帮助：收起时的样子，再展开「空间地图」一节
                Show-Page 'help'; $ctl.HelpScroll.ScrollToTop(); & $shot 'help'
                $sec = @(Get-HelpSections)[3]
                $sec.IsExpanded = $true; [void](& $waitUi { $false } 400)
                $y = $sec.TransformToAncestor($ctl.HelpScroll.Content).Transform((New-Object System.Windows.Point 0, 0)).Y
                $ctl.HelpScroll.ScrollToVerticalOffset([math]::Max(0, $y - 16)); & $shot 'help-map'
                $sec.IsExpanded = $false; $ctl.HelpScroll.ScrollToTop(); Show-Page 'clean'
            }
        }
    } catch { $L.Add('FAIL test run: ' + $_.Exception.Message); $script:uiFail++ }
    finally {
        try { if ($setBak) { [IO.File]::WriteAllBytes($script:settingsFile, $setBak) } elseif (Test-Path -LiteralPath $script:settingsFile) { Remove-Item -LiteralPath $script:settingsFile -Force } } catch {}
        try { [DiskMap]::MftOff = -not $fast0; [DupFinder]::LowPriority = ((Get-Setting 'LowIo' '0') -eq '1') } catch {}
    }
    $L.Add(("dialogs that would have opened: {0}" -f $script:uiSheets.Count))
    $L.Add(("summary: {0} failed" -f $script:uiFail))
    $file = if ($env:CLEANC_REPORT) { [IO.Path]::GetFullPath($env:CLEANC_REPORT) } else { Join-Path $script:appDir 'uitest.txt' }
    try { [IO.File]::WriteAllText($file, (@($L) -join "`r`n"), (New-Object Text.UTF8Encoding $true)) } catch {}
    $global:CLEANC_EXIT = [int]$script:uiFail
    $script:uiDone = $true
    if ($script:worker) { Set-CancelFlags; $script:closeWhenDone = $true }   # 还有后台在做：停在安全的地方再关
    $win.Close()
}

# ------------------------------------------------------------
# 定时器：把后台日志搬到界面、刷新进度、检测后台结束
# ------------------------------------------------------------
$timer = New-Object System.Windows.Threading.DispatcherTimer
$timer.Interval = [TimeSpan]::FromMilliseconds(300)
$timer.Add_Tick({
    while ($sync.Log.Count -gt 0) { UI-Log $sync.Log.Dequeue() }
    Update-CleanSummary
    if ($Error.Count -gt 0 -and -not [object]::ReferenceEquals($Error[0], $script:lastErrObj)) {
        $script:lastErrObj = $Error[0]
        $em = [string]$Error[0]
        if ($em -ne $script:lastErrMsg) { $script:lastErrMsg = $em; Write-LogFile ((T "[内部] ") + $em + "  @ " + ([string]$Error[0].InvocationInfo.PositionMessage).Split([char]10)[0]) }
    }

    if ([DupRow]::Dirty -and -not $script:worker) { [DupRow]::Dirty = $false; Update-DupSummary }
    if ([CandRow]::Dirty) { [CandRow]::Dirty = $false; Update-CandSel }
    if ($sync.Status -and $script:candRows -and $sync.StatusVer -ne $script:candSeen) {
        $script:candSeen = $sync.StatusVer
        foreach ($r in $script:candRows) { $v = $sync.Status[$r.Key]; if ($v) { $r.Status = $v[0]; $r.StatusBrush = $script:statusColor[[string]$v[1]] } }
    }

    if ($script:worker -and $script:op) { Update-Op }
    if ($script:odWanted -and -not $script:worker -and $ctl.PageSave.Visibility -eq 'Visible') { $script:odWanted = $false; Start-OneDriveInfo }
    if ($sync.Status -and $script:rows -and $sync.StatusVer -ne $script:statusSeen) {
        $script:statusSeen = $sync.StatusVer
        foreach ($r in $script:rows) {
            $v = $sync.Status[$r.Idx]
            if ($v) { $r.Status = $v[0]; $r.StatusBrush = $script:statusColor[[string]$v[1]] }
        }
    }

    if ($script:worker -and $script:worker.Handle.IsCompleted) {
        $w = $script:worker; $script:worker = $null
        $script:movedTargets = $null
        try { $w.PS.EndInvoke($w.Handle) | Out-Null } catch { UI-Log ((T "后台出错：{0}") -f $($_.Exception.Message)) }
        foreach ($er in @($w.PS.Streams.Error | Select-Object -First 5)) { UI-Log ((T "后台出错：{0}") -f $er) }
        $w.PS.Dispose(); $w.RS.Dispose()
        [DirStat]::Cancel = $false
        if ($sync.WasCancelled) { UI-Log (T '已中途取消。') }
        # 删过、搬过东西以后，逐个扫描得到的旧树不再拿来用（读文件表的结果靠变更日志更新）
        if (@('scan', 'movescan', 'apps', 'map', 'movesize', 'dup', 'update', 'startup', 'winget', 'odinfo', 'csanalyze', 'leftovers', 'recent') -notcontains [string]$sync.Mode) { [DiskMap]::Invalidate() }

        if ($sync.Mode -eq 'scan') {
            if ($sync.WasCancelled -or -not $sync.Sizes) {
                $script:oneClickPending = $false
                $sync.Sizes = $script:prevSizes
                End-Op $(if ($sync.WasCancelled) { (T '已中途取消，列表没有更新') } else { (T '没有完成') })
                if ($script:rows) { $ctl.Summary.Text = (T '扫描已取消，下面还是上一次扫描的结果。') }
                else { $ctl.Summary.Text = (T '扫描已取消。点「扫描」重新开始。'); $ctl.EmptyCleanText.Text = (T '扫描已取消。点「扫描」重新开始。') }
            } else {
                Build-Rows $sync.Sizes; End-Op (T '完成')
                if ($script:oneClickPending) { $script:oneClickPending = $false; $script:runAfterScan = $true }
            }
        }
        elseif ($sync.Mode -eq 'run') {
            $script:candScanned = $false
            $after = [double](FreeC); $freed = $after - $script:runFreeC0
            $cardWasOpen = ($ctl.Overlay.Visibility -eq 'Visible')
            $head = (T "C 盘剩余：{0} → {1}，释放了 {2}") -f (GB $script:runFreeC0), (GB $after), (GB ([math]::Max([double]0, [double]$freed)))
            $waitNote = ''
            if ([int]$sync.WaitCount -gt 0) {
                $waitNote = (T "有 {0} 个文件夹已经复制好，但原文件夹还被别的程序占着，没换成链接。彻底退出相关的聊天软件（包括右下角托盘图标）后再点一次「执行」，会接着用复制好的副本，很快完成。") -f [int]$sync.WaitCount
                $head += "`n" + $waitNote
            }
            $cx = [bool]$sync.WasCancelled
            if ($cx) { $head = (T '已中途取消：还没开始的项目都没做，已经做完的不会撤销。') + "`n" + $head }
            $endText = if ($cx) { (T "已中途取消，释放 {0}，C 盘现在剩余 {1}") } else { (T "完成，释放 {0}，C 盘现在剩余 {1}") }
            End-Op ($endText -f (GB ([math]::Max([double]0, [double]$freed))), (GB $after)) -KeepCard -headline $head -reportLines (Plan-Lines)
            if (-not $cx) { if ($ctl.Overlay.Visibility -eq 'Visible') { $script:askRemind = $true } else { $script:askRemindNow = $true } }
            $sumText = if ($cx) { (T "已中途取消：C 盘从剩余 {0} 变成 {1}。每一项的结果写在列表里；想看还剩什么，再点「扫描」。") } else { (T "已完成：C 盘从剩余 {0} 变成 {1}。每一项的结果写在列表里；想看还剩什么，再点「扫描」。") }
            $ctl.Summary.Text = $sumText -f (GB $script:runFreeC0), (GB $after)
            $script:reclaim = [double]0
            $lines = @(); if ($sync.RunSummary) { $lines = @($sync.RunSummary) }
            $shown = @($lines | Select-Object -First 22)
            if ($lines.Count -gt 22) { $shown += ((T "……另有 {0} 项，见左下角「运行记录」") -f ($lines.Count - 22)) }
            if (-not $cardWasOpen) { $script:pendingDialog = @{ Title = $(if ($cx) { (T '已中途取消') } else { (T '执行完成') }); Kind = $(if ($waitNote -or $cx) { 'warn' } else { 'done' }); Items = $shown
                Text = (T "共用时 {0}。C 盘剩余 {1} → {2}，释放 {3}。{4}") -f (FmtSpan $script:lastElapsed), (GB $script:runFreeC0), (GB $after), (GB ([math]::Max([double]0, [double]$freed))), $(if ($waitNote) { "`n`n" + $waitNote } else { '' }) } }
            try { [System.Media.SystemSounds]::Asterisk.Play() } catch {}
            Fill-DestChoices
        }
        elseif ($sync.Mode -eq 'hogs') { End-Op (T '完成') }
        elseif ($sync.Mode -eq 'similar') {
            $res = $sync.DupResult
            $cnt = if ($res) { $res.Count } else { 0 }
            $script:dupSimilar = $true
            $ctl.DupProgressText.Text = [string]$sync.SimNote
            End-Op ((T "完成，{0} 组相似照片") -f $cnt)
            if ($res) { Build-DupRows $res $cnt } else { Build-DupRows @() 0 }
            if ($script:dupRows -and $script:dupRows.Count -gt 0) {
                Pick-Dup 'none'
                UI-Log (T '相似照片不是同一个文件：没有自动勾选。每组第一张是分辨率最高的，看过以后自己勾要处理的；只能放进回收站或归档，不能永久删除，也不能合并。')
            } elseif (-not $sync.WasCancelled) { $ctl.EmptyDupText.Text = (T '没有找到相似的照片') }
        }
        elseif ($sync.Mode -eq 'dup') {
            $script:dupSimilar = $false
            $res = $sync.DupResult
            $cnt = if ($res) { $res.Count } else { 0 }
            $stopped = [DupFinder]::Cancel
            $ctl.DupProgressText.Text = ((T "{0}看过 {1:N0} 个文件夹、{2:N0} 个文件，找到 {3:N0} 组重复。") -f $(if ($stopped) { (T '已停止。') } else { (T '查找完成。') }), [DupFinder]::DirsSeen, [DupFinder]::FilesSeen, $cnt)
            End-Op $(if ($stopped) { ((T "已停止，找到 {0} 组") -f $cnt) } else { ((T "完成，找到 {0} 组") -f $cnt) })
            if ($res) { Build-DupRows $res $cnt } else { Build-DupRows @() 0 }
            if ($script:dupRows -and $script:dupRows.Count -gt 0) {
                Pick-Dup 'new'
                UI-Log (T '已自动勾选：每组留最新的一份，其余删除。可以改勾选，或点上面的按钮换一种留法。')
            }
        }
        elseif ($sync.Mode -eq 'dupdel' -or $sync.Mode -eq 'dupmove') {
            $moveMode = ($sync.Mode -eq 'dupmove')
            $gone = @{}
            if ($sync.DupDeleted) { foreach ($p in $sync.DupDeleted) { $gone[$p.ToLowerInvariant()] = $true } }
            $left = New-Object System.Collections.Generic.List[DupGroup]
            foreach ($g in $script:dupGroups) {
                $ng = New-Object DupGroup
                $ng.Name = $g.Name; $ng.Size = $g.Size; $ng.Verified = $g.Verified
                foreach ($f in $g.Files) { if (-not $gone.ContainsKey($f.Path.ToLowerInvariant())) { $ng.Files.Add($f) } }
                if ($ng.Files.Count -ge 2) { $left.Add($ng) }
            }
            Build-DupRows $left $left.Count
            $nDel = if ($sync.DupDeleted) { $sync.DupDeleted.Count } else { 0 }
            $cardWasOpen = ($ctl.Overlay.Visibility -eq 'Visible')
            if ($moveMode) {
                $cx = [bool]$sync.WasCancelled
                End-Op ($(if ($cx) { (T "已中途取消，归档了 {0} 个文件") } else { (T "完成，归档了 {0} 个文件") }) -f $nDel)
                UI-Log ((T "归档完成：{0} 个文件已搬到 {1}") -f $nDel, $sync.DupMoveDest)
            } else {
                $bin = if ($script:lastRecycle) { (T "`n`n文件在回收站里，清空回收站后才真正释放磁盘空间。") } else { '' }
                $binShort = if ($script:lastRecycle) { (T '文件在回收站里，清空回收站后才真正释放空间。') } else { '' }
                $cx = [bool]$sync.WasCancelled
                End-Op ($(if ($cx) { (T "已中途取消，删除了 {0} 个文件") } else { (T "完成，删除了 {0} 个文件") }) -f $nDel) -KeepCard -headline ($(if ($cx) { (T "已中途取消：删除了 {0} 个重复文件，剩下的没删。{1}") } else { (T "删除了 {0} 个重复文件。{1}") }) -f $nDel, $binShort) -reportLines @(,@((T '没删的（内容和保留的那份不完全相同，或文件被占用）记在左下角的「运行记录」里。'), '#6E6E73', $false))
                try { [System.Media.SystemSounds]::Asterisk.Play() } catch {}
                if (-not $cardWasOpen) { $script:pendingDialog = @{ Title = $(if ($cx) { (T '已中途取消') } else { (T '删除完成') }); Kind = 'done'; Text = ((T "删除了 {0} 个重复文件，共用时 {1}。{2}`n`n没删的（内容和保留的那份不完全相同，或文件被占用）记在「运行记录」里。") -f $nDel, (FmtSpan $script:lastElapsed), $bin) } }
            }
        }
        elseif ($sync.Mode -eq 'map') {
            $root = $sync.MapResult
            $mm = [string]$sync.MapMethod; $secs = [double]$sync.MapMs / 1000
            # 读文件表时，读完以后（核对的时候）才点停止的，结果是完整的
            $stopped = ($mm -eq 'mft-partial') -or ([DiskMap]::Cancel -and $mm -notlike 'mft*')
            if ($sync.MapNote -and $mm -notlike 'mft*') { UI-Log ((T "空间地图：没能直接读取文件表（{0}），改为逐个文件夹扫描") -f $sync.MapNote) }
            if ($root) {
                $script:mapHow = if ($mm -eq 'mft-usn') { (T '按变更日志更新') } elseif ($mm -like 'mft*') { (T '直接读文件表') } else { (T '逐个文件夹扫描') }
                UI-Log ((T "空间地图：{0}，用时 {1:N1} 秒") -f $script:mapHow, $secs)
                [DiskMap]::Use($root)
                $script:mapMethod = $mm
                $script:mapRoot = $root; $script:mapCur = $root; $script:mapScanAt = Get-Date
                $script:movedTargets = $null
                $script:prevSnap = $null
                if (-not $stopped) { try { Update-Growth $root } catch { $script:growNote = (T '没能和上次比较') } } else { $script:growNote = (T '这次扫描中途停止了，不和上次比较') }
                End-Op ($(if ($stopped) { (T "已中途停止，看过 {0:N0} 个文件，共 {1}") } else { (T "完成，{0:N0} 个文件，共 {1}") }) -f $root.Files, (Fmt $root.Size))
                $script:recentRows = $null; $script:recentNote = ''
                if ($script:mapView -eq 'grow') { Set-MapView 'grow' } elseif ($script:mapView -eq 'files') { Show-MapOverview; Show-MapFiles } elseif ($script:mapView -eq 'types') { Show-MapTypes } elseif ($script:mapView -eq 'recent') { Show-MapOverview; Show-MapRecent } else { Show-MapLevel $root }
                if ($stopped) { $ctl.MapInfo.Text = (T '扫描中途停止了，下面只是已经看过的部分') }
                Add-History
            } else { End-Op (T '没有完成') }
            $ctl.BtnMapStop.IsEnabled = $false
        }
        elseif ($sync.Mode -eq 'mapdel') {
            $res = $sync.MapDel
            $okSet = @{}; if ($res) { foreach ($p in $res.Ok) { $okSet[([string]$p).ToLowerInvariant()] = $true } }
            foreach ($r in @($script:mapDelRows)) {
                if (-not $okSet.ContainsKey(([string]$r.Path).ToLowerInvariant())) { continue }
                if ($r.Node) { [DiskMap]::Detach($r.Node) }
                else {
                    $pn = [DiskMap]::Find($script:mapRoot, (Split-Path $r.Path -Parent))
                    if ($pn) { [DiskMap]::DropFile($pn, $r.Size, $r.Disk, [bool]$r.Shared) }
                    [DiskMap]::ForgetFile($r.Path)
                }
            }
            $nOk = $okSet.Count; $fails = @(); if ($res) { $fails = @($res.Fail) }
            $one = (@($script:mapDelRows).Count -eq 1)
            $txt = if ($sync.WasCancelled) { (T "已中途取消，删除了 {0} 项") -f $nOk } elseif ($fails.Count -eq 0) { $(if ($one) { (T "已删除 {0}") -f @($script:mapDelRows)[0].Name } else { (T "已删除 {0} 项") -f $nOk }) } elseif ($nOk -eq 0) { (T '没有删掉') } else { (T "删除了 {0} 项，{1} 项没删掉") -f $nOk, $fails.Count }
            End-Op $txt
            if ($nOk -gt 0) { if ($script:mapView -eq 'files') { Show-MapFiles } elseif ($script:mapView -ne 'grow') { Show-MapLevel $script:mapCur } }
            if ($fails.Count -gt 0) {
                $script:pendingDialog = @{ Title = $(if ($nOk -eq 0) { (T '没有删掉') } else { (T '有的没有删掉') }); Kind = 'warn'; Items = @($fails | Select-Object -First 20)
                    Text = (T '下面这些没有删掉。正被别的程序打开的文件，关掉那个程序后再删一次。') }
            }
        }
        elseif ($sync.Mode -eq 'selftest') {
            $r = $sync.SelfTest
            if (-not $r) { End-Op (T '没有完成') }
            else {
                $text = (@($r.Lines) -join "`r`n")
                $file = Join-Path $script:appDir 'selftest.txt'
                try { New-Item -ItemType Directory -Force -Path $script:appDir | Out-Null; [IO.File]::WriteAllText($file, $text, (New-Object Text.UTF8Encoding $true)) } catch {}
                $copied = $true; try { [System.Windows.Clipboard]::SetText($text) } catch { $copied = $false }
                $x = $r.Res
                $sum = (T "{0} 项正常，{1} 项提醒，{2} 项有问题") -f $x.Pass, $x.Warn, $x.Fail
                End-Op $(if ($r.Stopped) { (T '已中途停止') } else { $sum })
                UI-Log ((T "检查扫描功能：{0}；结果存在 {1}") -f $sum, $file)
                $msg = $sum + (T '。') + $(if ($copied) { (T '结果已经复制，可以粘贴到 GitHub 的问题（Issue）里。') } else { '' }) + "`n`n" + ((T "完整结果存在 {0}") -f $file)
                if ($x.Fail -gt 0) { $msg += "`n`n" + (T '有问题的项目，扫描时会自动改用逐个文件夹扫描，不影响使用；把结果贴到 GitHub 的问题里可以帮助修好它。') }
                $script:pendingDialog = @{ Title = (T '扫描功能检查完了'); Kind = $(if ($x.Fail -gt 0) { 'warn' } else { 'done' }); Text = $msg
                    Buttons = @((T '好'), (T '打开结果')); Primary = (T '打开结果'); Cancel = (T '好'); Then = { Start-Process -FilePath "$env:SystemRoot\System32\notepad.exe" -ArgumentList ('"{0}"' -f $file) }.GetNewClosure() }
            }
        }
        elseif ($sync.Mode -eq 'update') {
            $u = $sync.Update
            End-Op (T '完成')
            if ($u -and $u.Ok -and -not ([string]$u.Tag).Trim()) { $u = @{ Ok = $false; Err = (T '返回的内容里没有版本号') } }   # 比如被网络登录页拦下来了
            # 版本号补齐到四段再比（2.6 和 2.6.0 是同一个版本）
            $norm = { param([string]$s) $v = $null; if ([version]::TryParse(([string]$s).Trim().TrimStart('v', 'V'), [ref]$v)) { New-Object Version ([math]::Max(0, $v.Major)), ([math]::Max(0, $v.Minor)), ([math]::Max(0, $v.Build)), ([math]::Max(0, $v.Revision)) } else { $null } }
            $cur = & $norm $script:AppVersion
            $new = if ($u -and $u.Ok) { & $norm $u.Tag } else { $null }
            $url = if ($u -and $u.Url -and ([string]$u.Url).StartsWith('https://github.com/')) { [string]$u.Url } else { $script:releasePage }
            $open = { Start-Process -FilePath "$env:SystemRoot\explorer.exe" -ArgumentList $url }.GetNewClosure()   # 用资源管理器打开：浏览器不会以管理员身份运行
            if (-not $u -or -not $u.Ok) {
                $script:pendingDialog = @{ Title = (T '没能检查新版本'); Kind = 'warn'; Text = ((T "连不上 GitHub：{0}`n`n可以直接打开下载页面看看。") -f $(if ($u) { $u.Err } else { '' }))
                    Buttons = @((T '好'), (T '打开下载页面')); Primary = (T '打开下载页面'); Cancel = (T '好'); Then = $open }
            } elseif ($new -and $cur -and $new -gt $cur) {
                $notes = @(([string]$u.Body -split "`r?`n") | Where-Object { $_ -match '^\s*[-*] ' } | Select-Object -First 6 | ForEach-Object { ($_ -replace '^\s*[-*]\s*', '' -replace '\*\*', '').Trim() })
                $script:pendingDialog = @{ Title = ((T "有新版本 {0}") -f $u.Tag); Kind = 'info'; Text = ((T "现在用的是 {0}。下载页面会在浏览器里打开，下载新的 exe 替换现在这个就好，设置都会保留。") -f $script:AppVersion); Items = $notes
                    Buttons = @((T '以后再说'), (T '打开下载页面')); Primary = (T '打开下载页面'); Cancel = (T '以后再说'); Then = $open }
            } else {
                $script:pendingDialog = @{ Title = (T '已经是最新版本'); Kind = 'done'; Text = ((T "现在用的是 {0}，GitHub 上最新的是 {1}。") -f $script:AppVersion, $u.Tag) }
            }
        }
        elseif ($sync.Mode -eq 'fcompress') {
            $x = $sync.FcResult
            if ($x) {
                $saved = [math]::Max([double]0, $x.Before - $x.After)
                End-Op ($(if ($x.Cancelled) { (T "已中途取消，省了 {0}") } else { (T "完成，省了 {0}") }) -f (Fmt $saved))
                $ctl.SaveFcState.Text = (T "上次压缩：{0}，实际占用 {1} → {2}，省了 {3}") -f $x.Path, (Fmt $x.Before), (Fmt $x.After), (Fmt $saved)
                $script:pendingDialog = @{ Title = $(if ($x.Cancelled) { (T '压缩已中途取消') } else { (T '压缩完成') }); Kind = 'done'; Text = ((T "{0}`n`n实际占用 {1} → {2}，省了 {3}。文件照常使用。") -f $x.Path, (Fmt $x.Before), (Fmt $x.After), (Fmt $saved)) + $(if ($x.Cancelled) { (T "`n`n已经压缩的文件保持压缩，剩下的没压缩。想压缩剩下的，再压缩一次这个文件夹就好。") } else { '' }) }
            } else { End-Op (T '没有完成') }
        }
        elseif ($sync.Mode -eq 'compactos') {
            $x = $sync.CosRes
            End-Op (T '完成')
            if ($x) { $script:pendingDialog = @{ Title = (T '系统压缩完成'); Kind = 'done'; Text = ((T "C 盘可用空间变化：{0}{1}") -f $(if ($x.Delta -ge 0) { (T '多了 ') } else { (T '少了 ') }), (Fmt ([math]::Abs($x.Delta)))) } }
            if ($ctl.PageSave.Visibility -eq 'Visible') { Load-Save }
        }
        elseif ($sync.Mode -eq 'odinfo') { End-Op (T '完成'); Show-OneDriveInfo $sync.OdInfo }
        elseif ($sync.Mode -eq 'odfree') {
            $x = $sync.OdRes
            End-Op (T '完成')
            if ($x) { $script:pendingDialog = @{ Title = (T '已标记为仅在线'); Kind = 'done'; Text = ((T "{0} 个文件（{1}）已改成仅在线{2}。OneDrive 会在后台释放本地空间，要等它同步一会儿。") -f $x.Done, (Fmt $x.Bytes), $(if ($x.Fail) { ((T "，{0} 个没改成（可能正被占用）") -f $x.Fail) } else { '' })) } }
            $script:odWanted = $true
        }
        elseif ($sync.Mode -eq 'csanalyze') {
            $x = $sync.CsRes
            End-Op (T '完成')
            if ($x -and $x.Ok) {
                $rec = if ($x.Recommended -match '(?i)^(yes|是|true)') { (T '建议清理') } else { (T '不需要清理') }
                $ctl.SaveCsState.Text = (T "当前：资源管理器显示 {0}，实际 {1}（其中和系统共用的 {2}），可回收的旧组件 {3} 个，上次清理 {4}。Windows 的判断：{5}。") -f $x.Reported, $x.Actual, $x.Shared, $x.Reclaimable, $x.LastCleanup, $rec
            } else { $ctl.SaveCsState.Text = (T '没分析成。') + $(if ($x) { ' ' + (($x.Out -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -Last 2) -join ' ') } else { '' }) }
        }
        elseif ($sync.Mode -eq 'wslmove') {
            $x = $sync.WslRes
            End-Op $(if ($x -and $x.Ok) { (T '已搬') } else { (T '没搬成') })
            if ($x -and $x.Ok) { $script:pendingDialog = @{ Title = (T 'WSL 发行版已搬到其他盘'); Kind = 'done'; Text = (T '照常用 wsl 打开即可。') } }
            elseif ($x -and $x.Old) { $script:pendingDialog = @{ Title = (T 'WSL 版本太旧'); Kind = 'warn'; Text = ((T "这个 WSL 还没有 --move 命令。在终端里运行 wsl --update 更新 WSL 后再试。`n`n{0}") -f $x.Out) } }
            elseif ($x) { $script:pendingDialog = @{ Title = (T '没搬成'); Kind = 'warn'; Text = $x.Out } }
            if ($ctl.PageSave.Visibility -eq 'Visible') { Load-Save }
        }
        elseif ($sync.Mode -eq 'leftovers') {
            End-Op (T '完成')
            Build-StartRows 'leftover' $sync.LeftoverResult
        }
        elseif ($sync.Mode -eq 'recent') {
            End-Op (T '完成')
            $script:recentRows = $sync.RecentResult
            $n = [string]$sync.RecentNote
            $script:recentNote = switch -Wildcard ($n) {
                'no-index' { (T '这块盘的文件表不在内存里了，再扫描一次就可以') }
                'no-journal' { (T '这块盘没有开变更日志（USN Journal），Windows 一般只给系统盘开') }
                'refs' { (T '这块盘的变更日志是 ReFS 的格式，暂时不认') }
                'journal-from:*' { (T "按变更日志统计，最近 {0} 天。日志只保留到 {1:yyyy-MM-dd HH:mm}，更早的改动看不到。大小按文件现在的大小算，删掉的只计个数；只列改动最集中的文件夹") -f $sync.RecentDays, [DateTime]::FromFileTimeUtc([long]$n.Substring(13)).ToLocalTime() }
                default { (T "按变更日志统计，最近 {0} 天。大小按文件现在的大小算（日志里没有写了多少字节），删掉的只计个数；只列改动最集中的文件夹") -f $sync.RecentDays }
            }
            if ($script:mapView -eq 'recent') { Show-MapRecent }
        }
        elseif ($sync.Mode -eq 'vdisk') {
            $x = $sync.VdRes
            End-Op (T '完成')
            if ($x) {
                $t = if ($x.After -lt $x.Before) { (T "{0} → {1}，省了 {2}。") -f (Fmt $x.Before), (Fmt $x.After), (Fmt ($x.Before - $x.After)) } else { (T "大小没有变化（{0}）。可能里面本来就没有可回收的空间，或者虚拟磁盘还在使用中。`n`n{1}") -f (Fmt $x.After), $x.Out }
                $script:pendingDialog = @{ Title = (T '虚拟磁盘压缩完成'); Kind = $(if ($x.After -lt $x.Before) { 'done' } else { 'info' }); Text = $t }
            }
            Load-Save
        }
        elseif ($sync.Mode -eq 'vmove') {
            $script:candScanned = $false; if ($ctl.PageMoves.Visibility -eq 'Visible') { $script:candPending = $true }
            $res = $sync.VmRes
            $ok = $res -and $res.Done -gt 0
            $cx = $res -and $res.Cancelled -and -not $ok
            End-Op $(if ($ok) { (T "已搬 {0}") -f (GB $res.Moved) } elseif ($cx) { (T '已取消') } else { (T '没搬成') })
            $msg = if ($res -and $res.Msgs) { ($res.Msgs -join "`n") } else { '' }
            $script:pendingDialog = @{ Title = $(if ($ok) { (T '搬好了') } elseif ($cx) { (T '已取消') } else { (T '没搬成') }); Kind = $(if ($ok) { 'done' } elseif ($cx) { 'info' } else { 'warn' }); Text = $(if ($ok) { (T "已搬到 {0}。原位置留了链接，软件照常使用。{1}") -f ($res.Dest -join (T '；')), $msg } else { $msg }) }
            Load-Save; Fill-DestChoices
        }
        elseif ($sync.Mode -eq 'appmove') {
            $script:candScanned = $false; if ($ctl.PageMoves.Visibility -eq 'Visible') { $script:candPending = $true }
            $res = $sync.AmRes; $r = $script:appMoveRow
            $ok = $res -and $res.Done -gt 0
            $cx = $res -and $res.Cancelled -and -not $ok
            End-Op $(if ($ok) { (T "已搬 {0}") -f (GB $res.Moved) } elseif ($cx) { (T '已取消') } else { (T '没搬成') })
            $msg = if ($res -and $res.Msgs) { ($res.Msgs -join "`n") } else { '' }
            if ($ok) {
                $script:pendingDialog = @{ Title = ((T "「{0}」搬好了") -f $r.Name); Kind = 'done'
                    Text = ((T "已搬到 {0}，C 盘腾出约 {1}。原位置留了链接，快捷方式和开始菜单照常能打开。建议现在打开一次这个软件，确认一切正常。`n`n要搬回来，到「搬家管理」点「搬回 C 盘」。{2}") -f ($res.Dest -join (T '；')), (GB $res.Moved), $(if ($msg) { "`n`n$msg" } else { '' })) }
            } else { $script:pendingDialog = @{ Title = $(if ($cx) { (T '已取消') } else { (T '没搬成') }); Kind = $(if ($cx) { 'info' } else { 'warn' }); Text = $(if ($msg) { $msg } else { (T '没有搬，原文件夹没动。') }) } }
            $script:runAfterApps = $true
            Fill-DestChoices
        }
        elseif ($sync.Mode -eq 'apps') {
            End-Op $(if ($sync.WasCancelled) { (T '已中途取消，没统计到的软件显示安装时登记的大小') } else { (T '完成') })
            if ($sync.AppsResult) { Build-AppRows $sync.AppsResult } else { $ctl.EmptyAppsText.Text = (T '没读到已安装的软件') }
        }
        elseif ($sync.Mode -eq 'startup') {
            End-Op (T '完成')
            Build-StartRows ([string]$sync.StartKind) $sync.StartResult
        }
        elseif ($sync.Mode -eq 'winget') {
            End-Op $(if ($sync.WingetResult -and -not $sync.WingetResult.Err) { ((T "{0} 个有新版本") -f @($sync.WingetResult.Items).Count) } else { (T '没查成') })
            Apply-WingetResult $sync.WingetResult
        }
        elseif ($sync.Mode -eq 'uninst') {
            $x = $sync.UninstRes
            End-Op $(if ($x -and $x.Ok) { (T '已卸载') } else { (T '没卸载成') })
            if ($x -and -not $x.Ok) { $script:pendingDialog = @{ Title = (T '没卸载成'); Kind = 'warn'; Text = $x.Msg } }
            $script:runAfterApps = $true
        }
        elseif ($sync.Mode -eq 'leftdel') {
            $x = $sync.LeftRes
            $cx = [bool]$sync.WasCancelled
            End-Op $(if ($cx) { (T '已中途取消') } else { (T '完成') })
            $ctl.AppsLeftBox.Visibility = 'Collapsed'; $script:leftApp = $null
            if ($x) { $script:pendingDialog = @{ Title = $(if ($cx) { (T '已中途取消') } else { (T '残留已清理') }); Kind = 'done'; Text = ((T "「{0}」留下的 {1} 个文件夹已移到回收站。清空回收站后才真正腾出空间。") -f $x.Name, $x.Count) + $(if ($cx) { (T '剩下的没删。') } else { '' }) } }
            $script:runAfterApps = $true
        }
        elseif ($sync.Mode -eq 'movescan') {
            End-Op $(if ($sync.WasCancelled) { (T '已中途取消') } else { (T '完成') })
            if ($sync.WasCancelled -or $null -eq $sync.CandResult) {
                $script:candScanned = $false
                $ctl.EmptyCandText.Text = (T '已取消。点右上角「刷新」重新看。')
                Set-CandInfo (T '已取消，没有看完。')
                if ($script:movesTab -eq 'cand') { $ctl.EmptyCand.Visibility = 'Visible' }
            } else {
                $script:storeChat = @($sync.CandStore)
                $ctl.CandStoreText.Text = if ($script:storeChat.Count -gt 0) { (T "{0} 是从应用商店装的，由 Windows 管理，本工具不搬。可以在 Windows 设置 → 应用 → 已安装的应用 里点它右边的「…」→「移动」，连同数据换到其他盘（要这个应用支持）。") -f ($script:storeChat -join (T '、')) } else { '' }
                Build-CandRows $sync.CandResult
                Set-MovesTab $script:movesTab
            }
        }
        elseif ($sync.Mode -eq 'movemany') {
            $x = $sync.MmRes
            $after = [double](FreeC); $freed = [math]::Max([double]0, [double]($after - $script:mmFreeC0))
            $cx = [bool]$sync.WasCancelled
            $cardWasOpen = ($ctl.Overlay.Visibility -eq 'Visible')
            $head = (T "C 盘剩余：{0} → {1}，腾出了 {2}") -f (GB $script:mmFreeC0), (GB $after), (GB $freed)
            if ($cx) { $head = (T '已中途取消：还没开始的项目都没做，已经做完的不会撤销。') + "`n" + $head }
            $waitNote = ''
            if ([int]$sync.WaitCount -gt 0) { $waitNote = (T "有 {0} 个文件夹已经复制好，但原文件夹还被别的程序占着，没换成链接。彻底退出相关的软件（包括右下角托盘图标）后再搬一次，会接着用复制好的副本，很快完成。") -f [int]$sync.WaitCount; $head += "`n" + $waitNote }
            End-Op ($(if ($cx) { (T "已中途取消，腾出 {0}") } else { (T "完成，腾出 {0}") }) -f (GB $freed)) -KeepCard -headline $head -reportLines (Plan-Lines)
            # 搬好的从「可以搬的」里去掉，其余的保留这次的结果
            if ($x -and $x.Done -and $x.Done.Count -gt 0 -and $script:candList) {
                $gone = @{}; foreach ($k in $x.Done) { $gone[[string]$k] = $true }
                $keep = @($script:candList | Where-Object { $k = if ($_.Type -eq 'app') { 'a:' + ([string]$_.Location).ToLowerInvariant() } else { 'c:' + $_.Idx }; -not $gone.ContainsKey($k) })
                Build-CandRows $keep
                $script:candSeen = -1
            }
            if (-not $cardWasOpen) {
                $lines = @(); if ($x -and $x.Summary) { $lines = @($x.Summary) }
                $script:pendingDialog = @{ Title = $(if ($cx) { (T '已中途取消') } else { (T '搬家完成') }); Kind = $(if ($waitNote -or $cx) { 'warn' } else { 'done' }); Items = @($lines | Select-Object -First 22); Text = $head }
            }
            try { [System.Media.SystemSounds]::Asterisk.Play() } catch {}
            $script:pageLoaded.apps = $false
            $script:runAfterMoves = $true
            Fill-DestChoices
        }
        elseif ($sync.Mode -eq 'movesize') {
            $t = $sync.MoveTotal
            if ($t -and $script:moveRows) { Set-DoneInfo ((T "共 {0} 个文件夹，其中 {1} 个正常，已经帮 C 盘腾出约 {2}。") -f $script:moveRows.Count, $t.Count, (Fmt $t.Bytes)) }
            if ($script:candPending) { $script:runAfterCand = $true }
        }
        elseif ($sync.Mode -eq 'moveback' -or $sync.Mode -eq 'movedrop') {
            $script:candScanned = $false; if ($ctl.PageMoves.Visibility -eq 'Visible') { $script:candPending = $true }
            $x = $sync.MoveRes
            $ok = $x -and $x.Ok
            $back = ($sync.Mode -eq 'moveback')
            $cx = $x -and $x.Cancelled -and -not $ok
            End-Op $(if ($ok) { (T '完成') } elseif ($cx) { (T '已取消') } else { (T '没有完成') })
            if ($ok) { $script:pendingDialog = @{ Title = $(if ($back) { (T '已搬回 C 盘') } else { (T '多余的副本已删除') }); Kind = 'done'; Text = $(if ($x.Msg) { $x.Msg } elseif ($back) { (T "搬回了 {0}，软件照常使用。") -f (Fmt $x.Bytes) } else { (T "腾出了 {0}。") -f (Fmt $x.Bytes) }) } }
            else { $script:pendingDialog = @{ Title = $(if ($cx) { (T '已取消') } else { (T '没有完成') }); Kind = $(if ($cx) { 'info' } else { 'warn' }); Text = $(if ($x) { $x.Msg } else { '' }) } }
            $script:runAfterMoves = $true
            Fill-DestChoices
        }
        elseif ($sync.Mode -eq 'merge') {
            $done = @{}
            if ($sync.DupMerged) { foreach ($p in $sync.DupMerged) { $done[$p.ToLowerInvariant()] = $true } }
            $left = New-Object System.Collections.Generic.List[DupGroup]
            foreach ($g in $script:dupGroups) {
                $ng = New-Object DupGroup
                $ng.Name = $g.Name; $ng.Size = $g.Size; $ng.Verified = $g.Verified
                foreach ($f in $g.Files) { if (-not $done.ContainsKey($f.Path.ToLowerInvariant())) { $ng.Files.Add($f) } }
                if ($ng.Files.Count -ge 2) { $left.Add($ng) }
            }
            Build-DupRows $left $left.Count
            $n = $done.Count
            $cx = [bool]$sync.WasCancelled
            End-Op ($(if ($cx) { (T "已中途取消，合并了 {0} 个文件") } else { (T "完成，合并了 {0} 个文件") }) -f $n) -KeepCard -headline ($(if ($cx) { (T "已中途取消：合并了 {0} 个重复文件，剩下的没合并。每个位置的文件都还在。") } else { (T "合并了 {0} 个重复文件。每个位置的文件都还在，只占一份空间。") }) -f $n) -reportLines @(,@((T '没合并的（内容不完全相同、文件正被打开、不在同一块盘）记在左下角的「运行记录」里。'), '#6E6E73', $false))
        }
        $sync.Mode = $null
        UI-Status; UI-Busy $false
        if ($script:closeWhenDone) { $script:pendingDialog = $null; $script:runAfterScan = $false; $script:askRemindNow = $false; $win.Close(); return }
        if ($script:runAfterScan) {
            $script:runAfterScan = $false
            Apply-OneClick
            Invoke-RunSelected (T '一键清理')
        }
        if ($script:runAfterApps) { $script:runAfterApps = $false; Load-Apps }
        if ($script:runAfterMoves) { $script:runAfterMoves = $false; Load-Moves }
        if ($script:runAfterCand) { $script:runAfterCand = $false; if (-not $script:worker) { Start-CandScan } }
        if ($script:candPending -and -not $script:worker -and $ctl.PageMoves.Visibility -eq 'Visible') { Start-CandScan }
        if ($script:pendingDialog) {
            # 先清掉再弹，避免对话框打开期间定时器再弹一次
            $d = $script:pendingDialog; $script:pendingDialog = $null
            if ($d.Buttons) {
                $ans = Show-Sheet -Kind $(if ($d.Kind) { $d.Kind } else { 'done' }) -Title $d.Title -Text $d.Text -Items $d.Items -Buttons $d.Buttons -Primary $d.Primary -Cancel $d.Cancel
                if ($d.Then -and $ans -eq $d.Primary) { try { & $d.Then } catch {} }
            } else { Show-Sheet -Kind $(if ($d.Kind) { $d.Kind } else { 'done' }) -Title $d.Title -Text $d.Text -Items $d.Items | Out-Null }
        }
        if ($script:askRemindNow) { $script:askRemindNow = $false; Ask-EnableRemind }
    }
})

# 有操作在进行时关窗口：不直接关（可能正停在换链接的半路上），先停在安全的地方，停好后自动关闭
$script:closeWhenDone = $false
$win.Add_Closing({
    param($s, $e)
    if (-not $script:worker) { return }
    $e.Cancel = $true
    if ($script:closeWhenDone) { return }
    $ans = Show-Sheet -Kind warn -Title (T '还有操作在进行中') -Text (T '现在直接关掉，可能留下搬了一半的文件夹。选「停下并关闭」会先停在安全的地方（正在做的这一小步会做完），然后自动关闭窗口。') -Buttons @((T '继续等待'), (T '停下并关闭')) -Primary (T '继续等待') -Cancel (T '继续等待')
    if ($ans -ne (T '停下并关闭')) { return }
    if (-not $script:worker) { $e.Cancel = $false; return }   # 对话框开着的时候已经做完了
    Set-CancelFlags
    $script:closeWhenDone = $true
    UI-Log (T '正在停下，停好后自动关闭窗口。')
})

$ctl.OvCancel.Add_Click({ Request-Cancel })
$ctl.OpCancel.Add_Click({ Request-Cancel })
$ctl.OvHide.Add_Click({ $ctl.Overlay.Visibility = 'Collapsed'; UI-Log (T '进度卡片已收起，进度见窗口底部和任务栏图标；做完会弹窗告诉你。') })
$ctl.OvClose.Add_Click({
    $ctl.Overlay.Visibility = 'Collapsed'; $script:cardShowsResult = $false
    if ($script:askRemind) { $script:askRemind = $false; Ask-EnableRemind }
})
# 第一次清理完，问一次要不要开启空间不足提醒（只问一次，选了什么都不再问）
function Ask-EnableRemind {
    $exe = [string]$env:CLEANC_SELF
    if (-not $exe -or -not (Test-Path -LiteralPath $exe) -or (Test-TempPath $exe) -or (Get-Setting 'AskedRemind' '') -eq '1' -or (Test-CleanTask $script:taskRemind)) { return }
    Set-Setting 'AskedRemind' '1'
    $ans = Show-Sheet -Title (T 'C 盘快满时提醒你？') -Text (T "开启后，每次登录电脑和每天中午，Windows 会在后台检查一次 C 盘。剩余空间低于 20 GB 时在屏幕右下角提醒你（每天最多一次），空间够就什么都不显示。`n`n不需要一直开着本工具，也不需要开机启动。以后可以在「自动提醒」页随时关掉。") -Buttons @((T '以后再说'), (T '开启提醒')) -Primary (T '开启提醒') -Cancel (T '以后再说')
    if ($ans -ne (T '开启提醒')) { return }
    $err = Enable-AutoTask $true
    if ($err) { Show-Sheet -Kind warn -Title (T '没开成') -Text $err | Out-Null; return }
    OpLog '系统设置' (T '开启空间不足提醒') $script:taskRemind ((T "任务计划：{0}") -f $exe)
    Show-Sheet -Kind done -Title (T '提醒已开启') -Text (T '在「自动提醒」页可以改提醒的界限，或者关掉。') | Out-Null
}

# 窗口大小跟着屏幕走：笔记本 150% 缩放时可用高度只有 690 左右，窗口太高会把下面的进度和记录挤出屏幕
$wa = [System.Windows.SystemParameters]::WorkArea
$win.Width     = [math]::Min([double]1240, [double]$wa.Width - 24)
$win.Height    = [math]::Min([double]860,  [double]$wa.Height - 24)
$win.MinWidth  = [math]::Min([double]980,  [double]$wa.Width - 24)
$win.MinHeight = [math]::Min([double]600,  [double]$wa.Height - 24)
if ($wa.Height -lt 800) { $ctl.LogPanel.Height = 130 }
$ctl.OvPlanScroll.MaxHeight = [math]::Max([double]80, [math]::Min([double]190, [double]$wa.Height - 560))
$win.Title = ((T "腾挪 ClearC {0}") -f $script:AppVersion)
Write-LogFile ((T "腾挪 ClearC {0}") -f $script:AppVersion + $(if ($script:AppBuild) { " ($($script:AppBuild))" } else { '' }))
$ctl.AppVer.Text = ((T "版本 {0}") -f $script:AppVersion)
Write-LogFile ((T "==== 腾挪 ClearC {0} 启动；Windows {1}；屏幕可用区域 {2:N0} x {3:N0}") -f $script:AppVersion, [Environment]::OSVersion.Version, $wa.Width, $wa.Height)
if ($script:themeFail) { Write-LogFile ((T "深色界面没能打开，这次用浅色：{0}") -f $script:themeFail) }

$script:statusColor = @{ wait = '#86868B'; run = '#0071E3'; ok = '#248A3D'; warn = '#B25000'; fail = '#D70015'; skip = '#86868B' }
$script:pendingDialog = $null
$win.TaskbarItemInfo = New-Object System.Windows.Shell.TaskbarItemInfo
Fill-DestChoices
UI-Status
Update-FilterSummary
Add-History
try { Repair-AutoTasks } catch {}
$pruned = Prune-OpLog (Get-LogMonths)
if ($pruned -gt 0) { OpLog '日志' (T '自动删除超过保存时间的旧记录') '' ((T "{0} 条，保存时间 {1} 个月") -f $pruned, (Get-LogMonths)) }
$timer.Start()

# 重新打开本工具（换语言、换外观后）
function Restart-App {
    try {
        if ($env:CLEANC_SELF -and (Test-Path -LiteralPath $env:CLEANC_SELF)) { Start-Process -FilePath $env:CLEANC_SELF }
        elseif ($script:selfScript) { Start-Process -FilePath "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -ArgumentList ('-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "{0}"' -f $script:selfScript) }
    } catch {}
    $win.Close()
}
# 外观：浅色 / 深色 / 跟随系统
$script:themeNames = @{ light = (T '浅色'); dark = (T '深色'); system = (T '跟随系统') }
$ctl.BtnThemeText.Text = (T "外观：{0}") -f $script:themeNames[$(if ($script:themeNames.ContainsKey($script:themePref)) { $script:themePref } else { 'light' })]
$ctl.BtnTheme.Add_Click({
    if ($script:worker) { Show-Sheet -Title (T '请等当前操作做完') -Text (T '另一个操作还在进行中。') | Out-Null; return }
    $ans = Show-Sheet -Title (T '选择外观') -Text ((T "深色适合在暗的环境里用；跟随系统会照 Windows 设置里「选择应用模式」来。换了以后本工具会关闭，再自动打开。`n`n现在：{0}") -f $script:themeNames[$script:themePref]) `
        -Buttons @((T '取消'), (T '跟随系统'), (T '深色'), (T '浅色')) -Primary (T '浅色') -Cancel (T '取消')
    $to = if ($ans -eq (T '浅色')) { 'light' } elseif ($ans -eq (T '深色')) { 'dark' } elseif ($ans -eq (T '跟随系统')) { 'system' } else { '' }
    if (-not $to -or $to -eq $script:themePref) { return }
    Set-ThemePref $to
})
function Set-ThemePref([string]$to) {
    Set-Setting 'Theme' $to
    OpLog '系统设置' (T '切换外观') $to ''
    Restart-App
}
# 设置页上点了外观：问一下再换（返回 $false：没换）
function Request-Theme([string]$to) {
    if ($to -eq $script:themePref) { return $false }
    if ($script:worker) { Show-Sheet -Title (T '请等当前操作做完') -Text (T '另一个操作还在进行中。') | Out-Null; return $false }
    $ok = (T '换')
    if ((Show-Sheet -Title ((T "换成「{0}」外观？") -f $script:themeNames[$to]) -Text (T '本工具会关闭，然后用新的外观重新打开。') -Buttons @((T '取消'), $ok) -Primary $ok -Cancel (T '取消')) -ne $ok) { return $false }
    Set-ThemePref $to
    return $true
}
# 界面语言切换：存到设置里，关掉本窗口，用新语言重新打开（返回 $false：没换）
$ctl.BtnLangText.Text = if ($script:Lang -eq 'en') { '中文' } else { 'English' }
function Request-Lang {
    if ($script:worker) { Show-Sheet -Title (T '请等当前操作做完') -Text (T '另一个操作还在进行中。') | Out-Null; return $false }
    $to = if ($script:Lang -eq 'en') { 'zh' } else { 'en' }
    if ($to -eq 'en') { $t = '切换为英文界面？'; $x = "本工具会关闭，然后以英文界面重新打开。`n`nClearC will close and reopen in English."; $ok = '切换'; $no = '取消' }
    else { $t = 'Switch to Chinese?'; $x = "ClearC will close and reopen in Chinese.`n`n本工具会关闭，然后以中文界面重新打开。"; $ok = 'Switch'; $no = 'Cancel' }
    if ((Show-Sheet -Title $t -Text $x -Buttons @($no, $ok) -Primary $ok -Cancel $no) -ne $ok) { return $false }
    Set-Setting 'Lang' $to
    OpLog '系统设置' (T '切换界面语言') $to ''
    try {
        if ($env:CLEANC_SELF -and (Test-Path -LiteralPath $env:CLEANC_SELF)) { Start-Process -FilePath $env:CLEANC_SELF }
        elseif ($script:selfScript) { Start-Process -FilePath "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -ArgumentList ('-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "{0}"' -f $script:selfScript) }
    } catch {}
    $win.Close()
    return $true
}
$ctl.BtnLang.Add_Click({ [void](Request-Lang) })
$ctl.CleanScroll.Add_ScrollChanged({ Update-CleanMore })
$ctl.CleanMore.Add_Click({ $ctl.CleanScroll.PageDown() })
# 第一次打开时先给出安全风险提示，勾选同意后才能使用；同意过就不再弹
$script:riskFile = Join-Path $env:LOCALAPPDATA 'CleanC\risk-accepted.txt'
$win.Add_ContentRendered({
    try { $sync.Hwnd = [long](New-Object System.Windows.Interop.WindowInteropHelper $win).Handle } catch { $sync.Hwnd = [long]0 }
    if (-not $script:startLogged) {
        $script:startLogged = $true
        $shown = $script:startClock.Elapsed.TotalSeconds
        $proc = 0.0; try { $proc = ((Get-Date) - (Get-Process -Id $PID).StartTime).TotalSeconds } catch {}
        Write-LogFile ((T "启动用时 {0:N1} 秒：准备 {1:N1} 秒，加载界面 {2:N1} 秒，显示 {3:N1} 秒") -f [math]::Max($proc, $shown), $script:tPrep, ($script:tUi - $script:tPrep), ($shown - $script:tUi))
    }
    if ($script:uiTest) {
        if (-not $script:uiStarted) {
            $script:uiStarted = $true
            # 万一卡住：四分钟后自己关掉（截图时要扫两遍盘）
            $script:uiWatch = New-Object System.Windows.Threading.DispatcherTimer; $script:uiWatch.Interval = [TimeSpan]::FromMinutes(4)
            $script:uiWatch.Add_Tick({
                $script:uiWatch.Stop(); if (-not $script:uiDone) { $global:CLEANC_EXIT = 99 }
                $win.Close()
                if ($win.IsVisible) { [Environment]::Exit(99) }   # 关不掉（比如后台还在做）：直接结束这次测试
            })
            $script:uiWatch.Start()
            [void]$win.Dispatcher.BeginInvoke([Action]{ Invoke-UiTest }, [System.Windows.Threading.DispatcherPriority]::ApplicationIdle)
        }
        return
    }
    if ($script:riskShown) { return }
    $script:riskShown = $true
    if (Test-Path -LiteralPath $script:riskFile) { return }
    $ans = Show-Sheet -Kind warn -Title (T '使用前请先阅读安全风险提示') `
        -Text (T "本工具会按你的选择删除或搬移电脑上的文件。删除的文件可能无法恢复，存在资料丢失的风险。`n`n每次删除前，请确认这些资料确实不再需要、删除不会给你带来损失；重要资料请先备份。因使用本工具造成的资料丢失或其他损失，责任由使用者自行承担，开发者不承担责任。`n`n完整说明随时可以在左侧「帮助」里查看。") `
        -Confirm (T '我已阅读并了解上述风险，同意自行承担使用本工具的后果。') -Buttons @((T '退出'), (T '同意并继续')) -Primary (T '同意并继续') -Cancel (T '退出')
    if ($ans -ne (T '同意并继续')) { $win.Close(); return }
    try {
        New-Item -ItemType Directory -Path (Split-Path $script:riskFile) -Force | Out-Null
        [IO.File]::WriteAllText($script:riskFile, ((T "{0:yyyy-MM-dd HH:mm:ss}  已同意（版本 {1}）") -f (Get-Date), $script:AppVersion), [Text.Encoding]::UTF8)
    } catch {}
    Write-LogFile (T '用户已同意安全风险提示')
})
$global:CLEANC_UI_SHOWN = $true   # 告诉外层 exe：界面已经正常打开
if ($script:uiTest) { $win.WindowStartupLocation = 'Manual'; $win.Left = -32000; $win.Top = -32000; $win.ShowActivated = $false; $win.ShowInTaskbar = $false }
$win.ShowDialog() | Out-Null
